"""Unique facts M-626 through M-755."""

from __future__ import annotations


def facts() -> dict[int, dict]:
    F: dict[int, dict] = {}

    def a(n, stmt, exq, exa, gq, ga, trap, q1, a1, q2, a2):
        F[n] = dict(stmt=stmt, exq=exq, exa=exa, gq=gq, ga=ga, trap=trap, q1=q1, a1=a1, q2=q2, a2=a2)

    # O real-number foundations
    a(626, r"Least-upper-bound property: every nonempty $S\subset\mathbb{R}$ that is bounded above has a least upper bound $\sup S\in\mathbb{R}$. This is the completeness axiom for $\mathbb{R}$; it fails in $\mathbb{Q}$.",
      r"Let $S=\{q\in\mathbb{Q}:q^2<2\}$. Is $S$ bounded above in $\mathbb{Q}$? Does it have a least upper bound in $\mathbb{Q}$?",
      r"Yes (e.g. $2$). No: any rational upper bound $r$ can be decreased while remaining an upper bound, because $\sqrt{2}\notin\mathbb{Q}$.",
      r"Does $(0,1)$ have a least upper bound in $\mathbb{R}$?", r"Yes: $1$.",
      r"Claiming the LUB must lie in $S$ (that is a maximum, not a supremum).",
      r"Does $\mathbb{N}$ have a least upper bound in $\mathbb{R}$?", r"No: $\mathbb{N}$ is not bounded above.",
      r"If $S=\{x\in\mathbb{R}:x^2<2\}$, what is $\sup S$?", r"$\sqrt{2}$, which is not in $S$.")
    a(627, r"An upper bound of $S$ is any $M$ with $s\le M$ for all $s\in S$. The supremum $\sup S$ is the least upper bound. Equivalently: $M=\sup S$ iff $M$ is an upper bound and for every $\varepsilon>0$ there is $s\in S$ with $s>M-\varepsilon$.",
      r"Find $\sup(0,1)$ and $\sup\{1-1/n:n\in\mathbb{N}\}$.",
      r"Both equal $1$. Neither set contains $1$, so neither has a maximum.",
      r"$\sup\{n/(n+1):n\in\mathbb{N}\}$ equals", r"$1$.",
      r"Writing $\sup S=\infty$ as if $\infty$ were a real number without saying extended reals.",
      r"If $S=\{2,5,5,7\}$, $\sup S$.", r"$7$ (and $\max S=7$).",
      r"Is $\sup[-1,0)=\sup(-1,0)$?", r"Yes, both $0$.")
    a(628, r"A lower bound of $S$ is any $m$ with $m\le s$ for all $s\in S$. The infimum $\inf S$ is the greatest lower bound. $\inf S=-\sup(-S)$. For every $\varepsilon>0$ some $s$ satisfies $s<\inf S+\varepsilon$.",
      r"Find $\inf(0,1)$ and $\inf\{1/n:n\in\mathbb{N}\}$.",
      r"Both $0$. Neither set contains $0$.",
      r"$\inf\{(-1)^n:n\in\mathbb{N}\}$ equals", r"$-1$.",
      r"Confusing $\inf$ with $\min$: $\inf(0,1)$ is $0$, not a minimum.",
      r"$\inf\{x\in\mathbb{R}:x>2\}$.", r"$2$.",
      r"Relation between $\inf S$ and $\sup S$ if $S$ is nonempty and bounded.", r"$\inf S\le\sup S$.")
    a(629, r"Archimedean property: for every real $x$ there is $n\in\mathbb{N}$ with $n>x$. Equivalently, $\{1/n:n\in\mathbb{N}\}$ has infimum $0$: for every $\varepsilon>0$ some $n$ has $1/n<\varepsilon$. Thus $\mathbb{N}$ is unbounded above in $\mathbb{R}$.",
      r"Prove there is an integer $n$ with $n>100\pi$.",
      r"Archimedean: $\mathbb{N}$ is not bounded above, so some $n>100\pi$.",
      r"Does there exist $n$ with $0<1/n<10^{-9}$?", r"Yes: take $n>10^9$.",
      r"Thinking there is an infinite integer, or a smallest positive real.",
      r"Is there a largest integer?", r"No.",
      r"Why does $1/n\to 0$ need Archimedes?", r"To produce $N>1/\varepsilon$.")
    a(630, r"Density of rationals: if $a<b$ in $\mathbb{R}$, there exists $q\in\mathbb{Q}$ with $a<q<b$. Proof: choose $n>1/(b-a)$ (Archimedean), then some integer $m$ with $m/n\in(a,b)$. There are infinitely many such $q$.",
      r"Show there is a rational strictly between $\sqrt{2}$ and $\sqrt{2}+0.01$.",
      r"Density: the open interval is nonempty, hence contains a rational (e.g. a decimal truncation of $\sqrt{2}+0.005$).",
      r"Between $0$ and $1$ there are how many rationals?", r"Infinitely many (countably infinitely many).",
      r"Claiming the next rational after $0$ is $1/n$ for a fixed $n$.",
      r"Is $\pi$ a limit point of $\mathbb{Q}$?", r"Yes: every neighborhood contains rationals.",
      r"Can two reals have no rational between them?", r"Only if they are equal.")
    a(631, r"Density of irrationals: if $a<b$, there is an irrational $x$ with $a<x<b$. Construction: choose a rational $q$ in $(a-\sqrt{2},b-\sqrt{2})$, then $q+\sqrt{2}$ is irrational and lies in $(a,b)$. Equivalently, $\mathbb{R}\setminus\mathbb{Q}$ is dense.",
      r"Produce an irrational in $(0,1/100)$.",
      r"$\sqrt{2}/200$ works: $0<\sqrt{2}/200<1.5/200<1/100$.",
      r"Is there an irrational between $3$ and $3.0001$?", r"Yes, e.g. $3+\sqrt{2}/10^5$.",
      r"Thinking irrationals are sparse because each has a complicated expansion.",
      r"Are the irrationals countable?", r"No: $\mathbb{R}$ uncountable and $\mathbb{Q}$ countable, so the complement is uncountable.",
      r"$q+\sqrt{2}$ for $q\in\mathbb{Q}$ is always", r"irrational.")
    a(632, r"Nested interval theorem: if $I_n=[a_n,b_n]$ are closed, bounded, nested ($I_{n+1}\subset I_n$), then $\bigcap_n I_n\neq\emptyset$. If also $b_n-a_n\to 0$, the intersection is a single point. Open nested intervals need not intersect: $\bigcap(0,1/n)=\emptyset$.",
      r"What is $\bigcap_{n=1}^\infty[0,1/n]$?",
      r"$\{0\}$. Lengths $\to 0$, so unique point.",
      r"Is $\bigcap_n(0,1+1/n)$ empty?", r"No: it equals $(0,1]$. The intervals are open but not nested down to a point in the same way; they are nested and the intersection is nonempty.",
      r"Dropping closedness: $\bigcap(0,1/n)=\emptyset$ even though nested and lengths $\to 0$.",
      r"$\bigcap_n[n,\infty)$.", r"Empty: the sets are nested closed but unbounded, so the theorem's boundedness hypothesis fails.",
      r"Why closed and bounded both matter.", r"Closed: open nested can miss the limit. Bounded: $[n,\infty)$ nested closed unbounded, empty intersection.")
    # O sequences
    a(633, r"A sequence $(a_n)$ in $\mathbb{R}$ converges to $L$ if the terms become and remain arbitrarily close to $L$: the tail lies in every neighborhood of $L$. The limit is unique when it exists. Convergence implies boundedness; the converse is false.",
      r"Does $a_n=(-1)^n$ converge? Does $a_n=1/n$?",
      r"No: terms oscillate between $-1$ and $1$. Yes: $1/n\to 0$.",
      r"If $a_n\to L$ and $a_n\to M$, then", r"$L=M$.",
      r"Calling a sequence convergent because it is bounded, or because $a_{n+1}-a_n\to 0$ (harmonic counterexample).",
      r"Is every convergent sequence bounded?", r"Yes.",
      r"Give a bounded divergent sequence.", r"$(-1)^n$.")
    a(634, r"Epsilon-$N$ definition: $a_n\to L$ iff for every $\varepsilon>0$ there exists $N\in\mathbb{N}$ such that $n\ge N$ implies $|a_n-L|<\varepsilon$. The $N$ may depend on $\varepsilon$ (and on the sequence), not on a particular $n$.",
      r"Prove $1/n\to 0$ from the definition.",
      r"Let $\varepsilon>0$. Choose integer $N>1/\varepsilon$. Then $n\ge N$ implies $|1/n|<\varepsilon$.",
      r"To have $|a_n-2|<10^{-3}$ eventually, one must produce", r"some $N$ working for this $\varepsilon=10^{-3}$.",
      r"Taking $N$ depending on $n$, or fixing one $\varepsilon$ and claiming the limit.",
      r"Does $N$ have to be the smallest possible?", r"No: any sufficiently large $N$ works.",
      r"Show $n/(n+1)\to 1$: $|n/(n+1)-1|=1/(n+1)<\varepsilon$ when", r"$n+1>1/\varepsilon$.")
    a(635, r"Limit laws: if $a_n\to A$ and $b_n\to B$ are finite, then $a_n\pm b_n\to A\pm B$, $a_nb_n\to AB$, and $a_n/b_n\to A/B$ if $B\neq 0$. Squeeze: $a_n\le c_n\le b_n$ and $a_n,b_n\to L$ imply $c_n\to L$. Algebra fails for $\infty-\infty$ or $0\cdot\infty$ forms.",
      r"If $a_n\to 2$ and $b_n\to 3$, find $\lim(a_n b_n-4)$.",
      r"$6-4=2$.",
      r"Does $a_n=n$, $b_n=1/n$ give $\lim a_nb_n=\lim a_n\lim b_n$?", r"No: left side $1$, right side is not a product of finite limits.",
      r"Applying quotient law when $b_n\to 0$.",
      r"Squeeze: $-1/n\le\sin n/n\le 1/n$ implies", r"$\sin n/n\to 0$.",
      r"If $a_n\to 0$ and $b_n$ bounded, $a_nb_n$.", r"Goes to $0$.")
    a(636, r"Monotone convergence theorem: a monotone bounded real sequence converges. An increasing sequence bounded above converges to its supremum; a decreasing sequence bounded below converges to its infimum. Boundedness is essential: $a_n=n$ increases but diverges.",
      r"Why does $a_n=(1+1/n)^n$ converge?",
      r"It is increasing and bounded above (e.g. by $3$), hence converges (to $e$).",
      r"A decreasing sequence of positive terms", r"converges (bounded below by $0$).",
      r"Using MCT in $\mathbb{Q}$: a bounded monotone sequence of rationals need not have a rational limit.",
      r"Does every increasing sequence converge in $\mathbb{R}$?", r"No: it must be bounded above.",
      r"If $a_n\uparrow$ and $a_n\le 10$, the limit is", r"$\sup\{a_n\}\le 10$.")
    a(637, r"A bounded monotone sequence is the standard way to manufacture a limit without naming it: show $a_{n+1}\ge a_n$ and $a_n\le M$, then $a_n\to\sup a_n$. Recurrences $a_{n+1}=f(a_n)$ are handled by checking monotonicity and an invariant bound.",
      r"$a_1=\sqrt{2}$, $a_{n+1}=\sqrt{2+a_n}$. Show $(a_n)$ converges and find the limit.",
      r"Induct: $a_n<a_{n+1}<2$. MCT gives a limit $L=\sqrt{2+L}$, so $L^2-L-2=0$, $L=2$ (positive).",
      r"If $0\le a_{n+1}\le a_n$, then $(a_n)$", r"converges to some $L\ge 0$.",
      r"Passing to the limit in $a_{n+1}=f(a_n)$ without first knowing $(a_n)$ converges.",
      r"$a_{n+1}=(a_n+2/a_n)/2$, $a_1=1$. Bound?", r"By AM-GM $a_n\ge\sqrt{2}$; decreasing after $a_2$, limit $\sqrt{2}$.",
      r"Why identify the limit by solving $L=f(L)$?", r"Continuity of $f$ and $a_{n+1}\to L$ too.")
    a(638, r"A subsequence $(a_{n_k})$ is obtained by a strictly increasing map $k\mapsto n_k\in\mathbb{N}$. If $a_n\to L$, every subsequence $\to L$. Conversely, if two subsequences have different limits, $(a_n)$ diverges. Every sequence has a monotone subsequence.",
      r"For $a_n=(-1)^n$, name two subsequences with different limits.",
      r"$a_{2k}\to 1$ and $a_{2k-1}\to -1$.",
      r"If every subsequence of $(a_n)$ converges, must $(a_n)$ converge?", r"Yes: all those limits coincide with $\lim a_n$.",
      r"Taking a sub-subsequence and changing the claimed limit of the original sequence.",
      r"Does $a_n=n$ have a bounded subsequence?", r"No.",
      r"If $a_{n_k}\to L$ along one subsequence, does $a_n\to L$?", r"Not necessarily.")
    a(639, r"Bolzano--Weierstrass: every bounded sequence in $\mathbb{R}$ (or $\mathbb{R}^d$) has a convergent subsequence. Proof: nested bisection of an interval containing all terms, or extract a monotone subsequence and apply MCT.",
      r"The sequence $a_n=(-1)^n(1+1/n)$ is bounded. Name a convergent subsequence and its limit.",
      r"Evens: $a_{2k}=1+1/(2k)\to 1$. Odds $\to -1$.",
      r"Does every sequence of reals have a convergent subsequence?", r"No: $a_n=n$ is unbounded, every subsequence $\to+\infty$.",
      r"Applying BW in $\mathbb{Q}$: a bounded sequence of rationals has a subsequence convergent in $\mathbb{R}$, not necessarily in $\mathbb{Q}$.",
      r"Is BW true in an incomplete space?", r"The subsequence may converge only in the completion.",
      r"A bounded sequence in $[0,1]$ has a subsequence converging to a point of", r"$[0,1]$ (closed).")
    a(640, r"$(a_n)$ is Cauchy if for every $\varepsilon>0$ there exists $N$ so that $m,n\ge N$ implies $|a_m-a_n|<\varepsilon$. Every convergent sequence is Cauchy. In $\mathbb{R}$ the converse holds. Cauchy sequences are bounded. $a_{n+1}-a_n\to 0$ is weaker than Cauchy.",
      r"Show that the partial sums $s_n=\sum_{k=1}^n 1/k$ are not Cauchy.",
      r"$s_{2n}-s_n=\sum_{k=n+1}^{2n}1/k\ge n\cdot(1/(2n))=1/2$, so $\varepsilon=1/2$ never works.",
      r"Is $a_n=\sqrt{n}$ Cauchy?", r"No: $|a_{4n}-a_n|=\sqrt{n}\to\infty$.",
      r"Inferring Cauchy from consecutive differences $\to 0$ (harmonic / $\sqrt{n}$).",
      r"If $(a_n)$ is Cauchy and a subsequence $\to L$, then", r"$a_n\to L$.",
      r"Are Cauchy sequences bounded?", r"Yes.")
    a(641, r"Completeness of the reals: every Cauchy sequence in $\mathbb{R}$ converges to a limit in $\mathbb{R}$. Equivalently: $\mathbb{R}$ has the least-upper-bound property. $\mathbb{Q}$ is not complete: a Cauchy sequence of rationals may converge to $\sqrt{2}\notin\mathbb{Q}$. Completeness is what makes $\varepsilon$-$N$ arguments close inside $\mathbb{R}$.",
      r"Why do decimal approximations $1$, $1.4$, $1.41$, $1.414$, $\ldots$ to $\sqrt{2}$ show $\mathbb{Q}$ is incomplete?",
      r"They form a Cauchy sequence in $\mathbb{Q}$ with no rational limit.",
      r"A Cauchy sequence of reals converges in", r"$\mathbb{R}$ (completeness).",
      r"Calling $\mathbb{R}$ complete because it is a field, or confusing algebraic completeness (FTA) with metric completeness.",
      r"Is $(0,1)$ complete in the usual metric?", r"No: $1/n$ is Cauchy and leaves the space.",
      r"Name two equivalent completeness statements for $\mathbb{R}$.", r"LUB property; Cauchy sequences converge; nested closed intervals with lengths $\to 0$ meet in a point.")
    a(642, r"$\limsup a_n=\inf_n(\sup_{k\ge n}a_k)$ and $\liminf a_n=\sup_n(\inf_{k\ge n}a_k)$, possibly $\pm\infty$. They are the largest and smallest subsequential limits in the extended reals. $(a_n)$ converges to a finite $L$ iff $\limsup a_n=\liminf a_n=L$. Always $\liminf\le\limsup$.",
      r"Compute $\limsup$ and $\liminf$ of $a_n=(-1)^n+1/n$.",
      r"Even terms $\to 1$, odd $\to -1$, so $\limsup=1$, $\liminf=-1$.",
      r"$a_n=n+(-1)^n n$: $\limsup$ and $\liminf$", r"Evens $4k\to+\infty$, odds $0$, so $\limsup=+\infty$, $\liminf=0$.",
      r"Thinking $\limsup$ is $\sup a_n$ rather than the limit of the tail-suprema.",
      r"If $a_n\to L$ finite, $\limsup a_n$.", r"$L$.",
      r"Sequence with $\liminf=0$, $\limsup=1$: example.", r"$a_n=\frac{1+(-1)^n}{2}$.")
    # O series
    a(643, r"The series $\sum_{n=1}^\infty a_n$ converges iff the sequence of partial sums $s_n=a_1+\cdots+a_n$ converges. The sum is $\lim s_n$. A necessary condition is $a_n\to 0$; it is not sufficient ($\sum 1/n$). Geometric series $\sum r^n$ converges iff $|r|<1$, sum $1/(1-r)$ from $n=0$.",
      r"Does $\sum_{n=0}^\infty(1/3)^n$ converge, and to what?",
      r"Yes, geometric $|r|=1/3<1$, sum $1/(1-1/3)=3/2$. Partial sums $s_n=(1-(1/3)^{n+1})/(1-1/3)\to 3/2$.",
      r"If $a_n\not\to 0$, then $\sum a_n$", r"diverges.",
      r"Confusing the series with the sequence of terms; claiming $\sum 1/n$ converges because $1/n\to 0$.",
      r"$s_n=1-1/2^n$ are partial sums of what geometric series?", r"$\sum_{k=1}^n 1/2^k$, sum $1$.",
      r"Does $\sum (-1)^n$ converge?", r"No: $a_n\not\to 0$.")
    a(644, r"Absolute convergence: $\sum|a_n|$ converges. Then $\sum a_n$ converges, and every rearrangement has the same sum. Absolute convergence is tested by comparison, ratio, root, integral tests on the nonnegative series $\sum|a_n|$.",
      r"Does $\sum (-1)^n/n^2$ converge absolutely?",
      r"Yes: $\sum 1/n^2$ is a convergent $p$-series, $p=2>1$.",
      r"Absolute convergence implies ordinary convergence: true or false?", r"True (triangle inequality on partial sums / completeness).",
      r"Concluding absolute convergence from ordinary convergence.",
      r"Is $\sum \sin n/n^2$ absolutely convergent?", r"Yes: $|\sin n|/n^2\le 1/n^2$.",
      r"Does $\sum (-1)^n/n$ converge absolutely?", r"No: harmonic series diverges.")
    a(645, r"Conditional convergence: $\sum a_n$ converges but $\sum|a_n|$ diverges. The alternating harmonic series $\sum (-1)^{n+1}/n$ is the prototype. Conditionally convergent series are sensitive to rearrangements (Riemann).",
      r"Classify $\sum (-1)^{n+1}/n$ as absolute, conditional, or divergent.",
      r"Conditional: Leibniz gives convergence; $\sum 1/n$ diverges.",
      r"Can a series of nonnegative terms be conditionally convergent?", r"No: $|a_n|=a_n$, so absolute and ordinary coincide.",
      r"Calling alternating harmonic absolutely convergent because it converges.",
      r"Classify $\sum (-1)^n/\sqrt{n}$.", r"Conditional ($p=1/2\le 1$ for absolute; Leibniz applies).",
      r"Classify $\sum (-1)^n/n^2$.", r"Absolute.")
    a(646, r"Comparison: if $0\le a_n\le b_n$ and $\sum b_n$ converges, so does $\sum a_n$; if $\sum a_n$ diverges, so does $\sum b_n$. Limit comparison: $a_n,b_n>0$ and $a_n/b_n\to L\in(0,\infty)$ imply $\sum a_n$ and $\sum b_n$ both converge or both diverge.",
      r"Does $\sum 1/(n^2+3n+1)$ converge?",
      r"Yes: $1/(n^2+3n+1)\le 1/n^2$, or limit-compare with $1/n^2$ (ratio $\to 1$).",
      r"Limit-compare $\sum\frac{n}{n^3-1}$ with", r"$\sum 1/n^2$; ratio $\to 1$, converges.",
      r"Comparing with a smaller divergent series and claiming divergence, or with a larger convergent series and claiming nothing.",
      r"Does $\sum 1/(n\log n)$ ($n\ge 2$) converge?", r"No: integral test / Cauchy condensation, compare with harmonic after grouping.",
      r"If $a_n\sim 1/n$, then $\sum a_n$", r"diverges.")
    a(647, r"Ratio test: $L=\lim |a_{n+1}/a_n|$ (if the limit exists). $L<1$ absolute convergence, $L>1$ (or $L=\infty$) divergence, $L=1$ inconclusive. Root test: $\rho=\limsup |a_n|^{1/n}$, same conclusions. Both are comparison with a geometric series.",
      r"Apply the ratio test to $\sum n!/n^n$.",
      r"$|a_{n+1}/a_n|=(n/(n+1))^n\to 1/e<1$, so the series converges absolutely.",
      r"Ratio test on $\sum 1/n$ and $\sum 1/n^2$ both give", r"$L=1$, inconclusive (one diverges, one converges).",
      r"Declaring divergence when $L=1$.",
      r"Root test on $\sum (2/3)^n$.", r"$(2/3)\to 2/3<1$, converges.",
      r"Ratio test for $\sum n^n x^n$ at $x=1/2$.", r"$|a_{n+1}/a_n|\to\infty$ if $x\neq 0$? At $x=1/2$: $\frac{(n+1)^{n+1}}{2^{n+1}}\frac{2^n}{n^n}=(n+1)(1+1/n)^n/2\to\infty>1$, diverges.")
    a(648, r"Leibniz alternating series test: if $b_n\ge 0$ is decreasing and $b_n\to 0$, then $\sum_{n=1}^\infty (-1)^{n+1} b_n$ converges. The remainder after $N$ terms has the sign of the next term and absolute value $\le b_{N+1}$.",
      r"Does $\sum_{n=2}^\infty (-1)^n\frac{\ln n}{n}$ converge?",
      r"Yes: $(\ln n)/n$ decreases to $0$ eventually (e.g. for $n\ge 3$), so Leibniz applies. Not absolutely ($p=1$ with log).",
      r"Error after the first four terms of $1-1/2+1/3-1/4+\cdots$ is at most", r"$1/5$.",
      r"Using Leibniz when $b_n$ is not eventually monotone ($b_n=1/n$ if $n$ odd, $1/n^2$ if even).",
      r"Does $\sum (-1)^n (1+1/n)$ converge?", r"No: terms $\not\to 0$.",
      r"Must $b_n$ be decreasing from $n=1$?", r"No: eventually decreasing is enough.")
    a(649, r"If $\sum a_n$ converges absolutely, every rearrangement converges to the same sum. If it converges only conditionally, Riemann's theorem: rearrangements exist with any prescribed real sum, or diverging to $\pm\infty$.",
      r"Can one rearrange $\sum (-1)^{n+1}/n$ so the sum is $100$?",
      r"Yes: conditionally convergent, Riemann.",
      r"Rearranging $\sum 1/n^2$ can change the sum?", r"No: absolute convergence.",
      r"Rearranging finitely many terms and thinking the sum can jump; only infinite rearrangements matter.",
      r"Does $\sum (-1)^n/n^2$ have rearrangement-invariant sum?", r"Yes, absolutely convergent.",
      r"Sketch how to rearrange alternating harmonic to exceed $2$.", r"Add enough positive terms (odd denominators) to pass $2$, then one negative term, repeat.")
    a(650, r"Cauchy criterion for series: $\sum a_n$ converges iff the tails are uniformly small: for every $\varepsilon>0$ there is $N$ so that $n\ge N$ and $p\ge 1$ imply $|a_{n+1}+\cdots+a_{n+p}|<\varepsilon$. Equivalent to $(s_n)$ being Cauchy, hence to completeness of $\mathbb{R}$.",
      r"Use Cauchy's criterion to show $\sum 1/n$ diverges.",
      r"The block from $n+1$ to $2n$ is $\ge 1/2$, so tails are not Cauchy.",
      r"For a geometric series with $|r|<1$, the tail $\sum_{k=n+1}^\infty r^k$ equals", r"$r^{n+1}/(1-r)\to 0$.",
      r"Checking only $p=1$ (i.e. $a_n\to 0$) and calling it the Cauchy criterion.",
      r"If Cauchy criterion holds, does $a_n\to 0$?", r"Yes ($p=1$).",
      r"Why is completeness used here?", r"$(s_n)$ Cauchy in $\mathbb{R}$ converges.")
    a(651, r"A power series $\sum_{n=0}^\infty c_n(x-a)^n$ has a radius of convergence $R\in[0,\infty]$ with $1/R=\limsup |c_n|^{1/n}$ (or ratio $|c_n/c_{n+1}|$ when that limit exists). The series converges (absolutely) for $|x-a|<R$ and diverges for $|x-a|>R$. Endpoints $x=a\pm R$ require separate tests.",
      r"Find $R$ for $\sum n! x^n$ and for $\sum x^n/n!$.",
      r"Ratio: first $|(n+1)x|\to\infty$ unless $x=0$, so $R=0$. Second $|x|/(n+1)\to 0$, so $R=\infty$.",
      r"For $\sum x^n/n$, the radius is $1$. At $x=1$ and $x=-1$?", r"$x=1$ harmonic diverges; $x=-1$ alternating harmonic converges (conditionally).",
      r"Declaring convergence at the endpoints from the value of $R$ alone.",
      r"Radius of $\sum (x-2)^n/2^n$.", r"$R=2$ (geometric $|x-2|/2<1$).",
      r"Inside the open disk of convergence, the series converges", r"absolutely.")
    # O continuity
    a(652, r"$f$ is continuous at $a$ if for every $\varepsilon>0$ there exists $\delta>0$ such that $0\le|x-a|<\delta$ (and $x$ in the domain) implies $|f(x)-f(a)|<\varepsilon$. Equivalent: $\lim_{x\to a}f(x)=f(a)$. Continuity on a set means continuity at every point of the set.",
      r"Prove $f(x)=x^2$ is continuous at $a=3$ by $\varepsilon$-$\delta$.",
      r"$|x^2-9|=|x-3||x+3|$. If $\delta\le 1$ then $|x+3|<7$, so $\delta=\min(1,\varepsilon/7)$ works.",
      r"$f(x)=1$ for $x\ge 0$ and $f(x)=0$ for $x<0$ is continuous at $0$?", r"No: left limit $0\neq f(0)=1$.",
      r"Choosing $\delta$ depending on $x$ rather than on $\varepsilon$ (and $a$).",
      r"Is a polynomial continuous on $\mathbb{R}$?", r"Yes.",
      r"$\delta$ may depend on which of $\varepsilon$ and $a$?", r"On both, in general.")
    a(653, r"Sequential continuity: $f$ is continuous at $a$ iff $x_n\to a$ (in the domain) implies $f(x_n)\to f(a)$. To prove discontinuity, exhibit one sequence $x_n\to a$ with $f(x_n)\not\to f(a)$. In metric spaces this is equivalent to the $\varepsilon$-$\delta$ definition.",
      r"Show that the Dirichlet function $1_{\mathbb{Q}}$ is discontinuous at every real $a$.",
      r"Take rationals $q_n\to a$ and irrationals $r_n\to a$: $f(q_n)=1$, $f(r_n)=0$, so the limit cannot exist.",
      r"If $x_n\to a$ and $f$ is continuous at $a$, then $f(x_n)$", r"converges to $f(a)$.",
      r"Using a single sequence that works to claim continuity (need all sequences).",
      r"Thomae's function $t(p/q)=1/q$, $t($irrational$)=0$: continuous where?", r"At irrationals, discontinuous at rationals.",
      r"Continuity of $f(x)=x$ at $0$ via sequences.", r"$x_n\to 0\Rightarrow f(x_n)=x_n\to 0$.")
    a(654, r"If $f,g$ are continuous at $a$, so are $f+g$, $fg$, and $f/g$ when $g(a)\neq 0$. Composition: $g$ continuous at $a$ and $f$ continuous at $g(a)$ imply $f\circ g$ continuous at $a$. Polynomials, rational functions on their domains, $\exp$, $\sin$, $\cos$ are continuous.",
      r"Where is $h(x)=\dfrac{\sin x}{x-1}$ continuous?",
      r"On $\mathbb{R}\setminus\{1\}$: quotient of continuous functions, denominator zero only at $1$.",
      r"Is $e^{\sin(x^2)}$ continuous on $\mathbb{R}$?", r"Yes: composition of continuous maps.",
      r"Cancelling a factor and restoring a removable discontinuity without checking the original formula's domain.",
      r"Product of two discontinuous functions can be continuous: example.", r"$1_{\mathbb{Q}}$ and $1_{\mathbb{R}\setminus\mathbb{Q}}$ multiply to $0$.",
      r"$|f|$ is continuous if $f$ is: true?", r"Yes: composition with $t\mapsto|t|$.")
    a(655, r"$f$ is uniformly continuous on $S$ if for every $\varepsilon>0$ there is $\delta>0$ working simultaneously for all $x,y\in S$: $|x-y|<\delta\Rightarrow|f(x)-f(y)|<\varepsilon$. Heine--Cantor: continuous on a compact set $\Rightarrow$ uniformly continuous. Uniform continuity $\Rightarrow$ Cauchy sequences map to Cauchy sequences.",
      r"Is $f(x)=x^2$ uniformly continuous on $\mathbb{R}$? On $[0,1]$?",
      r"No on $\mathbb{R}$: $|x^2-y^2|=|x+y||x-y|$ becomes large for large $x$. Yes on $[0,1]$ by Heine--Cantor.",
      r"Is $1/x$ uniformly continuous on $(0,1]$?", r"No: $x_n=1/n$, $y_n=1/(n+1)$ are close but $f$-values differ by about $1$.",
      r"Confusing pointwise continuity (local $\delta(a,\varepsilon)$) with a single $\delta(\varepsilon)$.",
      r"Is $\sqrt{x}$ uniformly continuous on $[0,\infty)$?", r"Yes: $|\sqrt{x}-\sqrt{y}|\le\sqrt{|x-y|}$.",
      r"Continuous functions on open intervals need not be uniform: classic.", r"$1/x$ on $(0,1)$, or $x^2$ on $\mathbb{R}$.")
    a(656, r"Intermediate Value Theorem: if $f$ is continuous on $[a,b]$ and $k$ lies between $f(a)$ and $f(b)$, then some $c\in[a,b]$ has $f(c)=k$. Proof idea: nested bisection, always keeping $k$ between the endpoint values; completeness produces $c$, and continuity forces $f(c)=k$. Equivalently, the continuous image of an interval is an interval.",
      r"Show $x^3+x-1=0$ has a root in $[0,1]$.",
      r"$f(0)=-1<0<1=f(1)$, IVT.",
      r"Does IVT require differentiability?", r"No: continuity on a compact interval is enough.",
      r"Applying IVT to a discontinuous function ($1_{\mathbb{Q}}$ misses values) or on an open set where the function blows up.",
      r"Must a continuous $f:\mathbb{R}\to\mathbb{R}$ be surjective if it takes both signs?", r"No: $\arctan$ takes both signs but misses $|y|\ge\pi/2$.",
      r"If $f([a,b])$ omits some value between $f(a)$ and $f(b)$, then $f$", r"cannot be continuous on $[a,b]$.")
    a(657, r"Extreme Value Theorem: a continuous real function on a compact interval $[a,b]$ attains its maximum and minimum. Proof idea: the image is bounded (else $1/(f(x_n)-n)$ tricks, or sequential compactness) and closed (sequential continuity), hence contains its supremum. Heine--Borel: compactness of $[a,b]$ is the engine.",
      r"Does $f(x)=x$ attain a maximum on $(0,1)$? On $[0,1]$?",
      r"No on $(0,1)$: $\sup=1$ not attained. Yes on $[0,1]$: max $1$ at $x=1$.",
      r"A continuous function on a closed bounded interval is", r"bounded and attains its bounds.",
      r"Applying EVT on $(0,1]$ to $1/x$, which is continuous there but the domain is not compact.",
      r"Proof sketch using sequences: take $x_n$ with $f(x_n)\to\sup f$. Then", r"BW gives $x_{n_k}\to c\in[a,b]$, and continuity gives $f(c)=\sup f$.",
      r"Does $e^{-x}$ on $[0,\infty)$ attain a minimum?", r"No: infimum $0$ not attained; domain not compact.")
    # O differentiability & integration
    a(658, r"The derivative at $a$ is $f'(a)=\lim_{h\to 0}\frac{f(a+h)-f(a)}{h}$ when the limit exists in $\mathbb{R}$. Equivalently $\lim_{x\to a}\frac{f(x)-f(a)}{x-a}$. Existence is a local linear-approximation statement: $f(a+h)=f(a)+f'(a)h+o(h)$.",
      r"Compute $f'(0)$ for $f(x)=x|x|$ from first principles.",
      r"Difference quotient is $|h|$ for $h\neq 0$, which $\to 0$. So $f'(0)=0$.",
      r"Is $|x|$ differentiable at $0$?", r"No: right quotient $+1$, left $-1$.",
      r"Using the power rule at a kink, or computing one-sided derivatives and averaging them.",
      r"Difference quotient of $x^2$ at $a=2$.", r"$h+4\to 4$.",
      r"If $f'(a)$ exists, is $f$ continuous at $a$?", r"Yes: $f(a+h)-f(a)=h\cdot($bounded$)\to 0$.")
    a(659, r"Mean Value Theorem: if $f$ is continuous on $[a,b]$ and differentiable on $(a,b)$, then some $c\in(a,b)$ satisfies $f'(c)=\frac{f(b)-f(a)}{b-a}$. Consequences: $f'=0$ implies $f$ constant on an interval; $f'\ge 0$ implies $f$ nondecreasing; uniqueness of ODE solutions at the GRE level.",
      r"Apply MVT to $f(x)=\sqrt{x}$ on $[0,1]$ and find $c$.",
      r"$f$ is continuous on $[0,1]$, differentiable on $(0,1)$. $\frac{1-0}{1}=1=\frac{1}{2\sqrt{c}}$, so $c=\frac14$.",
      r"If $|f'|\le 3$ on $\mathbb{R}$, then $|f(2)-f(0)|\le$", r"$6$.",
      r"Invoking MVT when $f$ fails to be differentiable at even one interior point where the conclusion can fail.",
      r"$f(x)=x^2$ on $[1,3]$: the MVT point $c$.", r"$f'(c)=4$, $c=2$.",
      r"If $f'(x)=0$ for all $x\in(a,b)$ and $f$ continuous on $[a,b]$, then $f$", r"is constant.")
    a(660, r"Rolle's theorem: if $f$ is continuous on $[a,b]$, differentiable on $(a,b)$, and $f(a)=f(b)$, then some $c\in(a,b)$ has $f'(c)=0$. It is MVT when the secant slope is zero. Between two roots of $f$ there is a root of $f'$.",
      r"Apply Rolle to $\sin x$ on $[0,\pi]$.",
      r"$\sin 0=\sin\pi=0$, so $\cos c=0$ for some $c\in(0,\pi)$, namely $c=\pi/2$.",
      r"A cubic with three real roots has a derivative with at least how many real roots?", r"Two (Rolle twice).",
      r"Forgetting $f(a)=f(b)$, or applying Rolle to $|x|$ on $[-1,1]$ (not differentiable at $0$).",
      r"Does Rolle give the location of $c$ explicitly?", r"Not in general: existence only.",
      r"Rolle for $f(x)=x^3-x$ on $[-1,1]$.", r"$f(\pm 1)=0$, $f'(x)=3x^2-1=0$ at $x=\pm 1/\sqrt{3}$.")
    a(661, r"Taylor's theorem: if $f$ is $n+1$ times differentiable, $f(x)=P_n(x)+R_n(x)$ where $P_n(x)=\sum_{k=0}^n\frac{f^{(k)}(a)}{k!}(x-a)^k$. Lagrange remainder: $R_n(x)=\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}$ for some $c$ between $a$ and $x$.",
      r"Write $P_2$ for $e^x$ at $0$ and bound $|R_2(x)|$ on $[0,1]$.",
      r"$P_2=1+x+x^2/2$. $R_2=e^c x^3/6$, so $|R_2|\le e/6$ on $[0,1]$.",
      r"Maclaurin polynomial of $\sin x$ of degree $3$.", r"$x-x^3/6$.",
      r"Treating the next Taylor term as exactly the remainder (it equals that term at an unknown $c$).",
      r"$P_1$ of $\ln(1+x)$ at $0$.", r"$x$.",
      r"If $f$ is a polynomial of degree $n$, $R_n$.", r"$0$.")
    a(662, r"Differentiability at $a$ implies continuity at $a$. The converse is false ($|x|$ at $0$). Differentiable functions need not be $C^1$: $f'$ may fail to be continuous. $C^1$ implies locally Lipschitz. Strict increase does not require $f'>0$ everywhere ($x^3$).",
      r"Give a function continuous on $\mathbb{R}$ but not differentiable at $0$, and one differentiable with $f'$ discontinuous at $0$.",
      r"$|x|$; $x^2\sin(1/x)$ for $x\neq 0$ and $0$ at $0$ (here $f'(0)=0$ but $f'$ has no limit at $0$).",
      r"Does $f'(a)=0$ imply a local extremum?", r"No: $f(x)=x^3$ at $0$.",
      r"Concluding $f'$ is continuous from the mere existence of $f'$.",
      r"Is $x^{1/3}$ differentiable at $0$?", r"No as a real derivative: difference quotients $\to+\infty$.",
      r"Differentiable $\Rightarrow$ continuous is used how in MVT proofs?", r"To apply EVT to $f$ or to an auxiliary function on $[a,b]$.")
    a(663, r"Darboux's theorem: if $f'$ exists on an interval, then $f'$ has the intermediate value property, even when $f'$ is discontinuous. Consequently $f'$ cannot have a simple jump discontinuity. Derivatives can still be discontinuous (oscillatory).",
      r"Why can there be no function with $f'(x)=0$ for $x<0$ and $f'(x)=1$ for $x\ge 0$?",
      r"That putative $f'$ would jump from $0$ to $1$, missing $(0,1)$, contradicting Darboux.",
      r"Does Darboux say $f'$ is continuous?", r"No: IVP is weaker than continuity.",
      r"Thinking every IVP function is a derivative, or that $f'$ is continuous almost by definition.",
      r"Classic $f'$ discontinuous at $0$.", r"$f(x)=x^2\sin(1/x)$, $f(0)=0$.",
      r"Can $f'$ have a jump discontinuity?", r"No: Darboux forbids jumps. It can fail to have a limit (oscillatory).")
    a(664, r"A partition $P=\{a=x_0<\cdots<x_n=b\}$ and tags $t_i\in[x_{i-1},x_i]$ give a Riemann sum $\sum_{i=1}^n f(t_i)\Delta x_i$. If $f$ is Riemann integrable, these sums approach $\int_a^b f$ as the mesh $\|P\|=\max\Delta x_i\to 0$, independently of tags.",
      r"Right Riemann sums for $f(x)=x$ on $[0,1]$ with $n$ equal parts.",
      r"$\sum_{k=1}^n (k/n)(1/n)=(n+1)/(2n)\to 1/2=\int_0^1 x\,dx$.",
      r"Mesh of the uniform partition of $[0,1]$ into $n$ intervals.", r"$1/n$.",
      r"Using left sums for an increasing $f$ and claiming they overestimate (they underestimate).",
      r"Left sums for $x^2$ on $[0,1]$, $n=2$.", r"$0\cdot\frac12+(1/2)^2\cdot\frac12=1/8$.",
      r"If all tags are midpoints, the sum is a", r"midpoint Riemann sum.")
    a(665, r"A bounded $f:[a,b]\to\mathbb{R}$ is Riemann integrable iff the upper and lower Darboux sums can be made arbitrarily close: for every $\varepsilon>0$ some partition has $U(f,P)-L(f,P)<\varepsilon$. Lebesgue's criterion: iff the set of discontinuities has measure zero. The Dirichlet function $1_{\mathbb{Q}}$ is not integrable on $[0,1]$; Thomae's function is.",
      r"Why is $1_{\mathbb{Q}}$ not Riemann integrable on $[0,1]$?",
      r"On every subinterval, $\sup f=1$ and $\inf f=0$, so $U-L=1$ for every partition.",
      r"A bounded function with a single jump is integrable?", r"Yes: one discontinuity, measure zero.",
      r"Claiming every bounded function is Riemann integrable, or that pointwise discontinuities always block integrability.",
      r"Is the step function $1_{[0,1/2]}$ integrable on $[0,1]$?", r"Yes: discontinuous only at $1/2$.",
      r"Thomae's function is integrable because it is continuous a.e.: where?", r"Continuous at irrationals, discontinuous at rationals (countable).")
    a(666, r"Every continuous $f:[a,b]\to\mathbb{R}$ is Riemann integrable: uniform continuity makes the oscillation on each subinterval $<\varepsilon$ when the mesh is small, hence $U-L<\varepsilon(b-a)$. Monotone functions are integrable (at most countably many jumps). Products of integrable functions need a proof; compositions may fail.",
      r"Why is $\sqrt{x}$ integrable on $[0,1]$ even though it is not differentiable at $0$?",
      r"It is continuous on a compact interval, hence integrable.",
      r"Is a monotone function on $[a,b]$ Riemann integrable?", r"Yes.",
      r"Requiring differentiability for integrability.",
      r"Is $|x|$ integrable on $[-1,1]$?", r"Yes, continuous.",
      r"Continuous on $(0,1]$ and unbounded: integrable on $[0,1]$?", r"No: Riemann theory requires a bounded function on a closed interval ($1/\sqrt{x}$ is improperly integrable).")
    a(667, r"Fundamental theorem: if $f$ is integrable on $[a,b]$ and $F(x)=\int_a^x f$, then $F$ is continuous; if $f$ is continuous at $c$, then $F'(c)=f(c)$. Conversely, if $F'=f$ is integrable, $\int_a^b f=F(b)-F(a)$. Chain rule form: $\frac{d}{dx}\int_{u(x)}^{v(x)}f=f(v)v'-f(u)u'$.",
      r"Differentiate $\int_0^{x^2}\sin t\,dt$.",
      r"$2x\sin(x^2)$ by FTC and chain rule.",
      r"$\int_0^\pi \cos t\,dt$ equals", r"$\sin\pi-\sin 0=0$.",
      r"Differentiating under the integral sign while forgetting the chain-rule factor from variable limits.",
      r"If $F'=f$ continuous, $\int_1^2 f$ in terms of $F$.", r"$F(2)-F(1)$.",
      r"Is $F(x)=\int_0^x 1_{\mathbb{Q}}$ differentiable?", r"$1_{\mathbb{Q}}$ is not integrable, so $F$ is not defined as a Riemann integral. For an integrable discontinuous $f$, $F'$ need not equal $f$ everywhere.")

    # P metric/topological basics
    a(668, r"A metric on a set $X$ is $d:X\times X\to[0,\infty)$ with $d(x,y)=0\Leftrightarrow x=y$, $d(x,y)=d(y,x)$, and $d(x,z)\le d(x,y)+d(y,z)$. Examples: Euclidean $|x-y|$, taxicab $\sum|x_i-y_i|$, discrete $d=1$ if $x\neq y$, $p$-adic. $d(x,y)=(x-y)^2$ on $\mathbb{R}$ fails the triangle inequality.",
      r"Show $d(x,y)=(x-y)^2$ is not a metric on $\mathbb{R}$.",
      r"$d(0,2)=4> d(0,1)+d(1,2)=1+1=2$, so triangle fails.",
      r"The discrete metric: $d(x,x)$ and $d(x,y)$ for $x\neq y$ are", r"$0$ and $1$.",
      r"Omitting $d(x,y)=0\Rightarrow x=y$ (pseudometrics) or using a squared Euclidean distance as if it were a metric.",
      r"Is $d(x,y)=|f(x)-f(y)|$ always a metric?", r"Iff $f$ is injective (otherwise identity of indiscernibles fails).",
      r"Does $d(x,y)=\min\{1,|x-y|\}$ satisfy the triangle inequality?", r"Yes: it is a bounded metric equivalent to the usual one.")
    a(669, r"The open ball $B_d(x,r)=\{y\in X:d(x,y)<r\}$ for $r>0$. Open balls form a basis for the metric topology: $U$ is open iff it is a union of open balls. In $(\mathbb{R},|\,\cdot\,|)$, $B(a,r)=(a-r,a+r)$. In the discrete metric, $B(x,1)=\{x\}$.",
      r"Describe $B((0,0),1)$ in $\mathbb{R}^2$ for the Euclidean metric and for the taxicab metric.",
      r"Open unit disk; open diamond $|x|+|y|<1$.",
      r"In the discrete metric, $B(x,1/2)$ equals", r"$\{x\}$.",
      r"Using $\le r$ for an open ball, or drawing Euclidean circles in the taxicab metric.",
      r"Is an open ball always an open set?", r"Yes, by the triangle inequality: about $y\in B(x,r)$ use radius $r-d(x,y)$.",
      r"$B(0,1)$ in $\mathbb{R}$ with $d(x,y)=\min\{1,|x-y|\}$.", r"$(-1,1)$, same as usual, because distances $<1$ agree with $|\,\cdot\,|$.")
    a(670, r"The closed ball $\overline{B}(x,r)=\{y:d(x,y)\le r\}$ is a closed set. It need not equal the closure of the open ball: in a discrete space with more than one point, $\mathrm{cl}\,B(x,1)=\{x\}$ while $\overline{B}(x,1)=X$. In $\mathbb{R}^n$ with the Euclidean metric they agree.",
      r"In a two-point discrete space $\{a,b\}$, compare $\mathrm{cl}\,B(a,1)$ with the closed ball of radius $1$ about $a$.",
      r"$B(a,1)=\{a\}$, already closed, so the closure is $\{a\}$. The closed ball $\{y:d(a,y)\le 1\}=\{a,b\}$.",
      r"Closed ball of radius $2$ about $0$ in $\mathbb{R}$ is", r"$[-2,2]$.",
      r"Assuming $\overline{B}(x,r)=\mathrm{cl}\,B(x,r)$ in every metric space.",
      r"Is a closed ball compact in every metric space?", r"No: closed ball of radius $1$ in an infinite discrete space is the whole space, not compact if infinite.",
      r"Is $\overline{B}(x,r)$ always closed?", r"Yes: complement is open by a triangle-inequality argument.")
    a(671, r"A set $U\subset X$ is open (in the metric topology) iff for every $x\in U$ there is $r>0$ with $B(x,r)\subset U$. Arbitrary unions of open sets are open; finite intersections are open. $X$ and $\emptyset$ are open. Infinite intersections of opens need not be open: $\bigcap (-1/n,1/n)=\{0\}$.",
      r"Is $(0,1)\cup(2,3)$ open in $\mathbb{R}$? Is $[0,1)$?",
      r"Yes (union of open intervals). No: no ball about $0$ stays in $[0,1)$.",
      r"Arbitrary unions of open sets are", r"open.",
      r"Claiming infinite intersections of open sets are open.",
      r"Is $\{x\}$ open in $\mathbb{R}$ with the usual metric?", r"No. It is open in the discrete metric.",
      r"Finite intersection of $( -1,1)$ and $(0,2)$.", r"$(0,1)$, open.")
    a(672, r"$F$ is closed iff $X\setminus F$ is open iff $F$ contains all its limit points iff $F$ is sequentially closed ($x_n\in F$, $x_n\to x$ imply $x\in F$). Arbitrary intersections and finite unions of closed sets are closed. Finite sets are closed in metric spaces. $\mathbb{Q}$ is not closed in $\mathbb{R}$.",
      r"Is $\{1/n:n\in\mathbb{N}\}$ closed in $\mathbb{R}$? What about $\{1/n\}\cup\{0\}$?",
      r"No: $1/n\to 0\notin$ the set. Yes: the only missing limit point has been added; complement is open.",
      r"Arbitrary intersections of closed sets are", r"closed.",
      r"Thinking closed means ``contains its endpoints'' without a metric/topology, or that bounded sets are closed.",
      r"Is $\mathbb{Z}$ closed in $\mathbb{R}$?", r"Yes: discrete subset, no limit points, or complement is a union of open intervals.",
      r"$[0,1)\cup(1,2]$ closed in $\mathbb{R}$?", r"No: $1$ is a limit point not in the set. Equivalently $1$ is missing.")
    a(673, r"A neighborhood of $x$ is a set $N$ containing an open set $U$ with $x\in U\subset N$. An open neighborhood is an open set containing $x$. Local properties (continuity, interior) are phrased with neighborhoods. In a metric space, open balls form a neighborhood basis.",
      r"Is $[0,1]$ a neighborhood of $1/2$ in $\mathbb{R}$? Of $0$?",
      r"Yes of $1/2$: it contains $(1/4,3/4)$. No of $0$: every open $U\ni 0$ meets the negatives, so no open $U\ni 0$ sits inside $[0,1]$.",
      r"Every open ball about $x$ is a neighborhood of", r"$x$.",
      r"Requiring a neighborhood to be open (some authors do; then ``neighborhood'' means open neighborhood).",
      r"Does a neighborhood of $x$ have to contain a ball $B(x,r)$ in a metric space?", r"Yes if it contains an open set containing $x$.",
      r"The whole space $X$ is a neighborhood of every point: true?", r"True.")
    a(674, r"The interior $\mathrm{int}(A)$ is the largest open set contained in $A$, equivalently $\{x\in A:\exists r>0,\, B(x,r)\subset A\}$. Always $\mathrm{int}(\mathrm{int} A)=\mathrm{int} A$. $\mathrm{int}[0,1]=(0,1)$, $\mathrm{int}\mathbb{Q}=\emptyset$ in $\mathbb{R}$.",
      r"Find $\mathrm{int}((0,1]\cup\{2\})$ in $\mathbb{R}$.",
      r"$(0,1)$: the point $1$ is not interior, and $2$ is isolated from the interval but still not interior in $\mathbb{R}$.",
      r"$\mathrm{int}\mathbb{Z}$ in $\mathbb{R}$ equals", r"$\emptyset$.",
      r"Calling an endpoint of a closed interval an interior point of that interval in $\mathbb{R}$.",
      r"$\mathrm{int}[0,1]$ in $\mathbb{R}$.", r"$(0,1)$.",
      r"Interior of a set relative to itself (subspace $[0,1]$): $\mathrm{int}_{[0,1]}[0,1]$.", r"$[0,1]$, the whole space.")
    a(675, r"The closure $\mathrm{cl}(A)=\overline{A}$ is the smallest closed set containing $A$, equivalently $A$ together with its limit points, equivalently $\{x:$ every neighborhood of $x$ meets $A\}$. $x\in\overline{A}$ iff some sequence in $A$ converges to $x$ (metric). $\overline{\mathbb{Q}}=\mathbb{R}$, $\overline{(0,1)}=[0,1]$.",
      r"Find $\overline{\{1/n:n\in\mathbb{N}\}}$ in $\mathbb{R}$.",
      r"$\{1/n:n\in\mathbb{N}\}\cup\{0\}$.",
      r"$\overline{(0,1)\cup(1,2)}$ equals", r"$[0,2]$.",
      r"Forgetting to add limit points that are not already in the set.",
      r"Closure of $\mathbb{Z}$ in $\mathbb{R}$.", r"$\mathbb{Z}$ (already closed).",
      r"Is $A\subset\overline{A}$ always?", r"Yes, and $A$ is closed iff $A=\overline{A}$.")
    a(676, r"The boundary $\partial A=\overline{A}\setminus\mathrm{int}(A)=\overline{A}\cap\overline{X\setminus A}$. A point is a boundary point iff every neighborhood meets both $A$ and its complement. $\partial[0,1]=\{0,1\}$, $\partial\mathbb{Q}=\mathbb{R}$ in $\mathbb{R}$. $A$ is closed iff $\partial A\subset A$; open iff $\partial A\cap A=\emptyset$.",
      r"Find $\partial(0,1]$ and $\partial\mathbb{Z}$ in $\mathbb{R}$.",
      r"$\{0,1\}$; $\mathbb{Z}$ (every integer is a boundary point, and there are no others).",
      r"$\partial\mathbb{Q}$ in $\mathbb{R}$ equals", r"$\mathbb{R}$.",
      r"Thinking the boundary of an interval is only the endpoints even after taking $\mathbb{Q}$ or a fat Cantor set.",
      r"Boundary of an open ball $B(0,1)$ in $\mathbb{R}$.", r"$\{-1,1\}$, the unit sphere in $1$D.",
      r"Is $\partial A$ always closed?", r"Yes: intersection of two closed sets.")
    a(677, r"A limit point (accumulation point) of $A$ is a point $x$ such that every punctured neighborhood of $x$ meets $A$. Isolated points of $A$ lie in $A$ but are not limit points. The derived set $A'$ is the set of limit points; $\overline{A}=A\cup A'$. Finite subsets of $\mathbb{R}$ have empty derived set.",
      r"What are the limit points of $\{1/n:n\in\mathbb{N}\}$ and of $\mathbb{Q}$ in $\mathbb{R}$?",
      r"$\{0\}$; all of $\mathbb{R}$.",
      r"Does a limit point of $A$ have to lie in $A$?", r"No: $0$ is a limit point of $(0,1)$.",
      r"Confusing limit points with interior points, or requiring infinitely many terms of a particular sequence.",
      r"Limit points of $\mathbb{Z}$ in $\mathbb{R}$.", r"None: each integer is isolated.",
      r"If $x$ is a limit point of $A$ in a metric space, there is a sequence of distinct points of $A$ converging to $x$: true?", r"True.")
    a(678, r"In a metric space, $x_n\to x$ iff $d(x_n,x)\to 0$ in $\mathbb{R}$. The limit is unique. A map $f$ is continuous iff it preserves sequential convergence. Subsequences of a convergent sequence converge to the same limit.",
      r"In $(\mathbb{R}^2,\|\,\cdot\,\|_2)$, does $(1/n,1-1/n)\to(0,1)$?",
      r"Yes: distance $\sqrt{(1/n)^2+(1/n)^2}\to 0$.",
      r"In a discrete metric space, which sequences converge?", r"Those that are eventually constant.",
      r"Using coordinatewise convergence without a metric, or thinking uniqueness of limits fails in metric spaces.",
      r"If $d(x_n,x)\to 0$ and $d(x_n,y)\to 0$, then", r"$x=y$ by the triangle inequality.",
      r"Does $x_n=1/n$ converge in $(0,1]$ with the usual metric?", r"No: the candidate $0$ is missing; the sequence is Cauchy but not convergent in the space.")
    a(679, r"A sequence is Cauchy in a metric space if for every $\varepsilon>0$ there is $N$ with $m,n\ge N\Rightarrow d(x_m,x_n)<\varepsilon$. Convergent $\Rightarrow$ Cauchy always. The converse is the definition of completeness. Cauchy sequences are bounded. $d(x_{n+1},x_n)\to 0$ is not sufficient.",
      r"Is $x_n=1/n$ Cauchy in $(0,1)$? Does it converge in $(0,1)$?",
      r"Yes Cauchy (same as in $\mathbb{R}$). No: $0\notin(0,1)$.",
      r"Every convergent sequence is Cauchy: true or false?", r"True, in any metric space.",
      r"Checking only consecutive terms $d(x_{n+1},x_n)\to 0$.",
      r"Is a Cauchy sequence in a discrete space eventually constant?", r"Yes: take $\varepsilon=1$.",
      r"Cauchy sequences are bounded: proof idea.", r"Fix $\varepsilon=1$, finitely many initial terms, plus a ball of radius $1$ about $x_N$.")
    a(680, r"A metric space is complete if every Cauchy sequence converges to a point of the space. $\mathbb{R}$, $\mathbb{R}^n$, $\mathbb{C}$, and $C[0,1]$ with the $\sup$ metric are complete. $\mathbb{Q}$, $(0,1)$, and $C[0,1]$ with $L^1$ are not. Completions exist and are unique up to isometry.",
      r"Why is $\mathbb{Q}$ incomplete? Why is $[0,1]$ complete?",
      r"Rationals approximating $\sqrt{2}$ are Cauchy with no rational limit. $[0,1]$ is a closed subset of the complete space $\mathbb{R}$, hence complete.",
      r"A closed subset of a complete metric space is", r"complete.",
      r"Confusing completeness with compactness, or algebraic closure of $\mathbb{C}$.",
      r"Is $(0,1]$ complete?", r"No: $1/n$ is Cauchy and escapes.",
      r"Name a complete space that is not compact.", r"$\mathbb{R}$, or any infinite-dimensional Banach space.")

    # P topological spaces
    a(681, r"A topology on $X$ is a collection $\tau\subset\mathcal{P}(X)$ containing $\emptyset$ and $X$, closed under arbitrary unions and finite intersections. Members of $\tau$ are open sets. Discrete topology: $\tau=\mathcal{P}(X)$. Indiscrete: $\{\emptyset,X\}$. Cofinite: complements finite (or the whole space). Metric topologies arise from metrics.",
      r"Is $\{\emptyset,\{a\},\{a,b\}\}$ a topology on $\{a,b\}$?",
      r"Yes: it contains $\emptyset$ and $X$, and is closed under the required unions and intersections.",
      r"The cofinite topology on $\mathbb{Z}$: is $\{n:n\neq 0\}$ open?", r"Yes, complement $\{0\}$ is finite.",
      r"Allowing arbitrary intersections of opens as a topology axiom (that would force a discrete-like algebra).",
      r"How many open sets in the discrete topology on a $3$-point set?", r"$8=2^3$.",
      r"Is the intersection of two topologies on $X$ a topology?", r"Yes. The union need not be.")
    a(682, r"A basis $\mathcal{B}$ for a topology: the basis elements cover $X$, and if $x\in B_1\cap B_2$ with $B_i\in\mathcal{B}$, some $B_3\in\mathcal{B}$ has $x\in B_3\subset B_1\cap B_2$. Open sets are arbitrary unions of basis elements. Metric balls form a basis; on $\mathbb{R}$, open intervals $(a,b)$ form a basis for the order topology.",
      r"Do the intervals $(a,b)$ with $a,b$ rational form a basis for the usual topology on $\mathbb{R}$?",
      r"Yes: a countable basis (second countability of $\mathbb{R}$).",
      r"In a metric space a standard basis is", r"the collection of all open balls.",
      r"Taking a cover by sets that fail the intersection condition (e.g. all infinite subsets of $\mathbb{N}$).",
      r"Is $\{\{x\}:x\in X\}$ a basis?", r"Yes: it generates the discrete topology.",
      r"Usual topology on $\mathbb{R}^2$: a basis of", r"open disks, or open rectangles $(a,b)\times(c,d)$.")
    a(683, r"A subbasis $\mathcal{S}$ generates a topology by taking finite intersections of members of $\mathcal{S}$ as a basis, then arbitrary unions. On $\mathbb{R}$, $\{(-\infty,a)\}\cup\{(a,+\infty)\}$ is a subbasis for the usual topology. The product topology is the coarsest topology making all projections continuous, generated by the subbasis $\pi_i^{-1}(U_i)$.",
      r"Finite intersections of $(-\infty,a)$ and $(b,+\infty)$ produce what basis elements?",
      r"Open rays and open intervals $(b,a)$ (when $b<a$), which generate the usual topology.",
      r"The product topology's subbasis consists of", r"inverse images of opens under the coordinate projections.",
      r"Confusing subbasis (finite intersections first) with basis (unions only).",
      r"Does a subbasis have to cover $X$?", r"No: the empty finite intersection is $X$, so $X$ is open in the generated topology anyway.",
      r"Subbasis of Sorgenfrey line: half-open intervals $[a,b)$. The generated topology is", r"finer than the usual topology on $\mathbb{R}$.")
    a(684, r"If $A\subset X$, the subspace topology is $\{U\cap A:U\text{ open in }X\}$. A set open in $A$ need not be open in $X$. If $d$ is a metric on $X$, the restricted metric on $A$ induces the subspace topology. $[0,1/2)$ is open in $[0,1]$, not in $\mathbb{R}$.",
      r"Is $[0,1)$ open in the subspace $[0,1]$? In $\mathbb{R}$?",
      r"Yes in $[0,1]$: $[0,1)=(-1,1)\cap[0,1]$. No in $\mathbb{R}$.",
      r"Closed sets in the subspace $A$ are", r"intersections of $A$ with closed sets of $X$.",
      r"Assuming every relatively open set is open in the ambient space.",
      r"Is $\{0\}$ open in $\mathbb{Z}\subset\mathbb{R}$ with the subspace topology?", r"Yes: $\{0\}=(-1/2,1/2)\cap\mathbb{Z}$.",
      r"Subspace topology on $\mathbb{Q}$: is $\{0\}$ open in $\mathbb{Q}$?", r"No: every ambient interval about $0$ contains other rationals.")
    a(685, r"The product topology on $X\times Y$ has basis $U\times V$ with $U$ open in $X$, $V$ open in $Y$. Projections are continuous and open. For infinite products $\prod X_i$, the product topology uses finitely many nontrivial open factors (box topology allows all). $\mathbb{R}^n$ is the $n$-fold product of $\mathbb{R}$.",
      r"Is $(0,1)\times(0,1)$ open in $\mathbb{R}^2$? Is the open unit disk a basis element?",
      r"Yes, a basis element. The disk is open but not a single rectangle; it is a union of rectangles (or balls).",
      r"Infinite product: is $\prod_{n=1}^\infty (0,1)$ open in $\mathbb{R}^{\mathbb{N}}$ with the product topology?", r"No: infinitely many nontrivial factors. It is open in the box topology.",
      r"Using box-style basic opens in an infinite product when the problem uses the product topology.",
      r"Projection $\pi_X:X\times Y\to X$ of an open set is", r"open.",
      r"Product of two compact spaces is compact: theorem?", r"Tychonoff (finite case is elementary).")
    a(686, r"$f:X\to Y$ is continuous iff $f^{-1}(V)$ is open in $X$ whenever $V$ is open in $Y$. Equivalent: preimages of closed sets are closed; or $f(\overline{A})\subset\overline{f(A)}$. In metric spaces this matches $\varepsilon$-$\delta$ and sequential continuity. Continuity is local.",
      r"Why is $f:\mathbb{R}_{\mathrm{usual}}\to\mathbb{R}_{\mathrm{discrete}}$, $f(x)=x$, not continuous?",
      r"$\{0\}$ is open in the discrete line, but $f^{-1}(\{0\})=\{0\}$ is not open in the usual topology.",
      r"Preimage of an open set under a continuous map is", r"open.",
      r"Claiming continuous maps send opens to opens (those are open maps, a stronger property).",
      r"Is a constant map continuous?", r"Yes: preimage of an open is either $\emptyset$ or $X$.",
      r"Identity $\mathrm{id}:(X,\tau)\to(X,\sigma)$ is continuous iff", r"$\tau$ is finer than $\sigma$.")
    a(687, r"A homeomorphism is a continuous bijection with continuous inverse (equivalently, a continuous open bijection). Homeomorphic spaces are indistinguishable topologically. $(0,1)\cong\mathbb{R}$ via $\tan$ (shifted). Compactness, connectedness, and Hausdorffness are homeomorphism invariants. $[0,1]\not\cong(0,1)$.",
      r"Why is $[0,1]$ not homeomorphic to $(0,1)$?",
      r"$[0,1]$ is compact, $(0,1)$ is not. (Or: removing an endpoint from $[0,1]$ leaves a connected space; removing any point from $(0,1)$ disconnects it.)",
      r"$(0,1)$ is homeomorphic to $\mathbb{R}$: exhibit a map.", r"$x\mapsto\tan(\pi(x-1/2))$, or $x\mapsto \frac{2x-1}{x(x-1)}$.",
      r"Producing a continuous bijection and forgetting to check that the inverse is continuous ($[0,2\pi)\to S^1$).",
      r"Are all intervals in $\mathbb{R}$ homeomorphic?", r"No: bounded closed intervals are compact; open ones are not. All open intervals (bounded or not) are homeomorphic.",
      r"$S^1$ vs $[0,1]$: homeomorphic?", r"No: deleting any point of $S^1$ leaves a connected space; deleting an interior point of $[0,1]$ disconnects it.")

    # P separation & compactness
    a(688, r"Hausdorff ($T_2$): distinct points have disjoint open neighborhoods. Metric spaces are Hausdorff. Limits of sequences (and nets) are unique. Compact subsets of Hausdorff spaces are closed. The infinite cofinite topology is $T_1$ but not Hausdorff.",
      r"Why does a sequence in a Hausdorff space have at most one limit?",
      r"If $x\neq y$, disjoint neighborhoods $U\ni x$, $V\ni y$ cannot both contain all but finitely many terms.",
      r"Is every metric space Hausdorff?", r"Yes: balls of radius $d(x,y)/2$.",
      r"Claiming the cofinite topology on an infinite set is Hausdorff.",
      r"In a Hausdorff space, are finite sets closed?", r"Yes (even $T_1$ suffices).",
      r"Product of Hausdorff spaces is", r"Hausdorff.")
    a(689, r"$T_1$: for $x\neq y$ there is an open $U\ni x$ with $y\notin U$ (and vice versa). Equivalent: singletons are closed. $T_2\Rightarrow T_1\Rightarrow T_0$. Infinite cofinite topology is $T_1$ not $T_2$. Discrete is $T_1$; indiscrete on two points is not.",
      r"Why is the cofinite topology on $\mathbb{Z}$ $T_1$ but not Hausdorff?",
      r"Singletons are finite, hence closed, so $T_1$. Any two nonempty opens have finite complements, hence infinite intersection, so not disjoint.",
      r"Singletons closed iff the space is", r"$T_1$.",
      r"Equating $T_1$ with Hausdorff.",
      r"Is $\mathbb{R}$ with the usual topology $T_1$?", r"Yes (it is even metrizable).",
      r"Finite complement topology on a finite set is", r"discrete, hence Hausdorff.")
    a(690, r"$X$ is compact if every open cover of $X$ has a finite subcover. Finite spaces are compact. $[0,1]$ is compact; $(0,1)$ and $\mathbb{R}$ are not. Closed subsets of compact spaces are compact; compact subsets of Hausdorff spaces are closed. Continuous images of compact sets are compact.",
      r"Give an open cover of $(0,1)$ with no finite subcover.",
      r"$\{(1/n,1):n\ge 2\}$: the union is $(0,1)$, and any finite subcollection has a largest $1/N$, missing $(0,1/N]$.",
      r"A closed subset of a compact space is", r"compact.",
      r"Calling a set compact because it is closed, or because it is bounded, without Heine--Borel hypotheses.",
      r"Is a finite union of compact sets compact?", r"Yes.",
      r"Infinite discrete space: compact?", r"No: cover by singletons has no finite subcover.")
    a(691, r"An open cover of $X$ is a family of open sets whose union is $X$. Compactness is: every such family has a finite subcover. Equivalent for metric spaces: every sequence has a convergent subsequence; every infinite subset has a limit point; complete and totally bounded.",
      r"The sets $U_n=(-n,n)$ cover $\mathbb{R}$. Why does this show $\mathbb{R}$ is not compact?",
      r"Any finite subcollection is contained in $(-N,N)$ for $N=\max n_i$, missing $|x|\ge N$.",
      r"A subcover is a", r"subcollection that still covers.",
      r"Using closed covers, or thinking one particular cover having a finite subcover is enough for compactness.",
      r"Cover $[0,1]$ by $\{( -1,1-1/n):n\ge 2\}\cup\{(1/2,2)\}$. Finite subcover?", r"Yes: the last interval plus one $U_n$ that reaches $1/2$; compactness guarantees some finite subcover for every cover.",
      r"Lebesgue number intuition: in a compact metric space, some $\delta>0$ has every set of diameter $<\delta$ inside a single set of the cover: true?", r"True.")
    a(692, r"If $f:X\to Y$ is continuous and $X$ is compact, then $f(X)$ is compact. Hence a continuous real function on a compact space is bounded and attains its extrema. A continuous bijection from a compact space onto a Hausdorff space is a homeomorphism.",
      r"Why does $f(x)=e^x$ fail to map $\mathbb{R}$ onto a compact set?",
      r"$\mathbb{R}$ is not compact; $f(\mathbb{R})=(0,\infty)$ is not compact. Continuity alone does not create compactness.",
      r"Continuous image of $[0,1]$ in $\mathbb{R}$ is", r"a closed bounded interval (connected compact).",
      r"Applying the theorem when the domain is $(0,1)$, or when $f$ is not continuous.",
      r"Projection $X\times Y\to X$ with $Y$ compact: closed map?", r"Yes (tube lemma / closed projection).",
      r"Continuous bijection $[0,2\pi)\to S^1$, $\theta\mapsto e^{i\theta}$: homeomorphism?", r"No: domain not compact, inverse fails continuity at $1$.")
    a(693, r"Sequential compactness: every sequence has a subsequence converging to a point of the space. In metric spaces, compact $\Leftrightarrow$ sequentially compact $\Leftrightarrow$ complete and totally bounded. Bolzano--Weierstrass is sequential compactness of closed bounded subsets of $\mathbb{R}^n$.",
      r"Why is $(0,1)$ not sequentially compact?",
      r"$x_n=1/n$ has no subsequence converging in $(0,1)$.",
      r"In metric spaces, compactness and sequential compactness are", r"equivalent.",
      r"Using sequential compactness as the definition in a general topological space (there it is weaker than compactness).",
      r"Is an infinite subset of a sequentially compact metric space guaranteed a limit point in the space?", r"Yes.",
      r"$[0,1]^{\mathbb{N}}$ with the product topology is compact by Tychonoff; metrizable?", r"Yes (countable product of metric intervals), hence sequentially compact.")
    a(694, r"Heine--Borel: a subset $K\subset\mathbb{R}^n$ is compact iff it is closed and bounded. Boundedness without closedness fails ($(0,1]$); closedness without boundedness fails ($\mathbb{Z}$). The theorem fails in infinite-dimensional normed spaces: the closed unit ball is not compact.",
      r"Which of $[0,1]$, $(0,1]$, $\mathbb{Z}$, $\{(x,y):x^2+y^2\le 1\}$ are compact in Euclidean space?",
      r"$[0,1]$ and the closed unit disk: closed and bounded. $(0,1]$ not closed. $\mathbb{Z}$ unbounded.",
      r"Closed and bounded in $\mathbb{R}^n$ implies", r"compact.",
      r"Using Heine--Borel in $\mathbb{Q}$ or in an infinite-dimensional space.",
      r"Is $\overline{B}(0,1)$ compact in $\ell^2$?", r"No: the standard basis vectors have no convergent subsequence.",
      r"$\{1/n\}\cup\{0\}$ compact in $\mathbb{R}$?", r"Yes: closed and bounded.")

    # P connectedness
    a(695, r"$X$ is connected if it is not the union of two nonempty disjoint open sets (in $X$), equivalently the only clopen subsets are $\emptyset$ and $X$. $\mathbb{R}$ and intervals are connected. $\mathbb{Q}$ is totally disconnected. A union of two intersecting connected sets is connected.",
      r"Is $[0,1]\cup[2,3]$ connected? Is $[0,1]\cup(1,2]$?",
      r"No: two disjoint clopen pieces. Yes: the union is $[0,2]$, an interval.",
      r"$\mathbb{Q}$ is connected in $\mathbb{R}$?", r"No: $\mathbb{Q}\cap(-\infty,\sqrt{2})$ and $\mathbb{Q}\cap(\sqrt{2},\infty)$ separate it.",
      r"Confusing connected with path-connected, or with ``has no holes'' in $\mathbb{R}^2$.",
      r"Is a singleton connected?", r"Yes.",
      r"Product of connected spaces is", r"connected.")
    a(696, r"$X$ is path-connected if any two points can be joined by a continuous path $\gamma:[0,1]\to X$. Path-connected $\Rightarrow$ connected; the converse fails (topologist's sine curve). $\mathbb{R}^n\setminus\{0\}$ is path-connected for $n\ge 2$, not for $n=1$. Convex sets are path-connected.",
      r"Is $\mathbb{R}\setminus\{0\}$ path-connected? $\mathbb{R}^2\setminus\{0\}$?",
      r"No: cannot join $-1$ to $1$ without hitting $0$. Yes: go around the origin on a circular arc or polygonal path.",
      r"Path-connected implies connected: true?", r"True. The converse is false.",
      r"Assuming $\mathbb{R}^2$ minus a point is disconnected (true in $\mathbb{R}^1$ only).",
      r"Open unit disk: path-connected?", r"Yes, it is convex: use straight-line paths.",
      r"Topologist's sine curve is the standard example of", r"connected but not path-connected.")
    a(697, r"The connected component of $x$ is the maximal connected subset containing $x$ (union of all connected sets containing $x$). Components partition $X$ and are closed. In $\mathbb{Q}$, components are singletons. In a locally connected space, components are open.",
      r"What are the connected components of $(0,1)\cup(2,3)$ and of $\mathbb{Q}$?",
      r"$(0,1)$ and $(2,3)$; singletons $\{q\}$.",
      r"Components are always", r"closed (in $X$).",
      r"Thinking components are always open (false for $\mathbb{Q}$).",
      r"How many components does $\mathbb{Z}$ have in the subspace topology from $\mathbb{R}$?", r"Countably infinitely many, one per integer.",
      r"Path-components vs components: which is finer?", r"Path-components sit inside components; they can be strictly smaller.")
    a(698, r"A continuous image of a connected space is connected. This is the topological form of the IVT: $f([a,b])$ is connected in $\mathbb{R}$, hence an interval, hence contains all intermediate values. There is no continuous surjection from a connected space onto a discrete two-point space.",
      r"Why is there no continuous $f:[0,1]\to\{0,1\}$ onto, with $\{0,1\}$ discrete?",
      r"The domain is connected, the codomain is not, and a continuous image would be connected.",
      r"Continuous image of $\mathbb{R}$ in $\mathbb{R}$ is", r"an interval (possibly unbounded, possibly a point).",
      r"Claiming the image of a disconnected space is disconnected (constant maps).",
      r"Projection of the connected set $\{(x,y):xy=1,x>0\}$ onto the $x$-axis.", r"$(0,\infty)$, connected.",
      r"If $X$ is connected and $f$ is continuous, can $f(X)$ be a single point?", r"Yes: constant functions.")
    a(699, r"A subset $A\subset\mathbb{R}$ (usual topology) is connected iff $A$ is an interval: whenever $a,b\in A$ and $a<c<b$, one has $c\in A$. Thus the connected subsets are (possibly infinite, open, closed, half-open, degenerate) intervals. This classification fails in $\mathbb{R}^2$.",
      r"Which of $(0,1)$, $[0,1]$, $[0,\infty)$, $\{0\}$, $[0,1]\cup[1,2]$, $[0,1]\cup[2,3]$ are connected in $\mathbb{R}$?",
      r"All except the last: $[0,1]\cup[1,2]=[0,2]$ is an interval. The last misses $(1,2)$.",
      r"Connected subsets of $\mathbb{R}$ are precisely", r"intervals.",
      r"Calling $\mathbb{Q}\cap[0,1]$ an interval, or thinking a disconnected set cannot be dense.",
      r"Is $\mathbb{R}\setminus\mathbb{Z}$ connected?", r"No: it is a countable disjoint union of open intervals.",
      r"A nonempty open connected subset of $\mathbb{R}$ is", r"an open interval (possibly infinite).")

    # Q propositional logic
    a(700, r"A proposition is a declarative sentence that is true or false (not both). ``$17$ is prime'' is a proposition; ``$x>3$'' is a predicate with a free variable; questions and commands are not propositions. Propositional logic studies truth-functional combinations of such atoms.",
      r"Which of ``$2+2=4$'', ``Is $n$ even?'', ``$n$ is even'' are propositions?",
      r"The first is a (true) proposition. The second is a question. The third is a predicate until $n$ is specified or quantified.",
      r"Is ``this statement is false'' a proposition in classical logic?", r"No: the liar paradox is excluded from the two-valued calculus.",
      r"Treating an open sentence $P(x)$ as a proposition with a definite truth value.",
      r"``Every even integer greater than $2$ is a sum of two primes'' is a proposition?", r"Yes: it is either true or false, even if unproved.",
      r"Truth value of $1=0$.", r"False.")
    a(701, r"The standard connectives are $\neg$ (not), $\wedge$ (and), $\vee$ (or, inclusive), $\to$ (implies), $\leftrightarrow$ (iff). They are truth-functional: the truth value of a compound is determined by the truth values of the parts. $\vee$ is not exclusive; $P\vee Q$ is true when both are true.",
      r"Translate ``$n$ is even or $n$ is a multiple of $3$ (or both)'' and its exclusive variant.",
      r"Inclusive: $E\vee T$. Exclusive: $(E\vee T)\wedge\neg(E\wedge T)$.",
      r"$P\wedge Q$ is true only when", r"both $P$ and $Q$ are true.",
      r"Reading ``or'' as exclusive in a mathematical definition (``$x\le 1$ or $x\ge 1$'' must include $x=1$).",
      r"Negation of ``$P$ and $Q$'' is not ``not $P$ and not $Q$'' but", r"``not $P$ or not $Q$'' (De Morgan).",
      r"How many binary truth functions of two atoms are there?", r"$2^{4}=16$.")
    a(702, r"A truth table lists all $2^n$ assignments of T/F to $n$ atoms and the resulting value of a formula. $P\to Q$ is false only in the row $P$ true, $Q$ false. Building a table is the brute-force decision procedure for propositional validity.",
      r"Write the four rows of $P\to Q$.",
      r"TT$\mapsto$T, TF$\mapsto$F, FT$\mapsto$T, FF$\mapsto$T.",
      r"The formula $P\vee\neg P$ is true in how many rows?", r"All of them (two rows if only $P$ is atomic).",
      r"Missing the vacuous-truth rows of implication, or writing $2n$ rows instead of $2^n$.",
      r"When is $P\leftrightarrow Q$ true?", r"When $P$ and $Q$ have the same truth value (TT and FF).",
      r"A formula in three atoms has how many rows?", r"$8$.")
    a(703, r"Formulas $A$ and $B$ are logically equivalent ($A\equiv B$) if they have the same truth value on every assignment, iff $A\leftrightarrow B$ is a tautology. Standard equivalences: $P\to Q\equiv\neg P\vee Q\equiv\neg(P\wedge\neg Q)$, double negation, De Morgan, distributivity, commutativity.",
      r"Show $P\to Q$ is equivalent to $\neg Q\to\neg P$.",
      r"Both fail only when $P$ is true and $Q$ is false. (Contrapositive.)",
      r"$P\wedge(P\to Q)$ is equivalent to", r"$P\wedge Q$.",
      r"Replacing a subformula by a formula that is not equivalent (algebraic cancellation that is not valid).",
      r"Is $P\to Q$ equivalent to $Q\to P$?", r"No (converse).",
      r"Simplify $\neg\neg P$.", r"$P$.")
    a(704, r"A tautology is a formula true under every truth assignment (valid propositional formula). Examples: $P\vee\neg P$, $P\to P$, $(P\to Q)\leftrightarrow(\neg Q\to\neg P)$. A substitution instance of a tautology is a tautology. Checking: truth table, or reduce via equivalences to $\top$.",
      r"Is $(P\wedge(P\to Q))\to Q$ a tautology?",
      r"Yes: modus ponens is valid; the implication is never false.",
      r"$P\to(Q\to P)$ is a tautology?", r"Yes (a paradox of material implication).",
      r"Calling a formula that is sometimes true a tautology (that is mere satisfiability).",
      r"Is $P\vee Q$ a tautology?", r"No: false when both atoms are false.",
      r"Negation of a tautology is a", r"contradiction.")
    a(705, r"A contradiction is a formula false under every assignment (unsatisfiable). Prototype: $P\wedge\neg P$. A set of formulas is inconsistent if some finite combination yields a contradiction. In a proof by contradiction one derives a contradiction from $\neg P$ and concludes $P$.",
      r"Show $(P\to Q)\wedge P\wedge\neg Q$ is a contradiction.",
      r"From $P$ and $P\to Q$ get $Q$, contradicting $\neg Q$. Truth table: no T row.",
      r"Is $P\wedge Q\wedge\neg P$ a contradiction even if $Q$ varies?", r"Yes: $P$ and $\neg P$ already clash.",
      r"Calling a single false instance (in a particular model) a contradiction of the formula as a schema.",
      r"Can a contradiction imply $Q$?", r"Yes: explosion, $P\wedge\neg P\to Q$ is a tautology.",
      r"Satisfiable but not a tautology: example.", r"$P$ itself, or $P\vee Q$.")
    a(706, r"Material implication $P\to Q$ is the truth function that is false only when $P$ is true and $Q$ is false. Vacuous truth: a false hypothesis implies any conclusion. In proofs, $P\to Q$ is established by assuming $P$ and deducing $Q$, or by proving the contrapositive.",
      r"Truth value of ``if $0=1$, then $2=3$'' as material implication.",
      r"True: the hypothesis is false.",
      r"To prove $P\to Q$ by assuming $P$, one must deduce", r"$Q$.",
      r"Rejecting a true implication because the hypothesis is false (vacuous truth), or treating $\to$ as causation.",
      r"When $P$ is true, $P\to Q$ has the same truth value as", r"$Q$.",
      r"Does $P\to Q$ assert that $P$ is true?", r"No.")
    a(707, r"The biconditional $P\leftrightarrow Q$ means $(P\to Q)\wedge(Q\to P)$: $P$ and $Q$ are equivalent in truth value. It is true on TT and FF, false on TF and FT. Definitions in mathematics are biconditionals. ``Iff'' is $\leftrightarrow$.",
      r"When is $(n\text{ even})\leftrightarrow(n^2\text{ even})$ true for $n\in\mathbb{Z}$?",
      r"For every $n$: both directions hold, so the biconditional is true as a universally quantified statement.",
      r"$P\leftrightarrow Q$ is equivalent to", r"$(P\wedge Q)\vee(\neg P\wedge\neg Q)$.",
      r"Proving only one direction of an iff claim.",
      r"Is $\leftrightarrow$ associative?", r"Yes as a truth function, but chains $P\leftrightarrow Q\leftrightarrow R$ in prose mean all three equivalent, not a particular association.",
      r"$P\leftrightarrow\neg P$ is a", r"contradiction.")
    a(708, r"For an implication $P\to Q$: the converse is $Q\to P$, the contrapositive is $\neg Q\to\neg P$, and the inverse is $\neg P\to\neg Q$. The contrapositive is equivalent to the original; the converse is equivalent to the inverse; neither pair matches the other in general.",
      r"For ``if $n$ is divisible by $4$, then $n$ is even'', write converse, contrapositive, and inverse.",
      r"Converse: even $\Rightarrow$ divisible by $4$ (false). Contrapositive: odd $\Rightarrow$ not divisible by $4$ (true). Inverse: not divisible by $4$ $\Rightarrow$ odd (false).",
      r"Which of converse/contrapositive/inverse is equivalent to $P\to Q$?", r"Only the contrapositive.",
      r"Proving the converse and claiming to have proved the implication.",
      r"Contrapositive of ``if $f$ is differentiable, then $f$ is continuous''.", r"If $f$ is not continuous, then $f$ is not differentiable.",
      r"Inverse of $P\to Q$ is equivalent to", r"the converse $Q\to P$.")
    a(709, r"De Morgan's laws: $\neg(P\wedge Q)\equiv\neg P\vee\neg Q$ and $\neg(P\vee Q)\equiv\neg P\wedge\neg Q$. Quantified forms: $\neg\forall x\,P\equiv\exists x\,\neg P$. Set forms: $(A\cap B)^c=A^c\cup B^c$. Use them to push negations inward to atoms.",
      r"Negate ``$x>0$ and $x<1$'' and ``$x\le 0$ or $x\ge 1$''.",
      r"``$x\le 0$ or $x\ge 1$''; ``$0<x<1$'' (i.e. $x>0$ and $x<1$). They are De Morgan duals.",
      r"$\neg(P\wedge\neg Q)$ simplifies to", r"$\neg P\vee Q$, which is $P\to Q$.",
      r"Writing $\neg(P\wedge Q)$ as $\neg P\wedge\neg Q$.",
      r"Set form of the first De Morgan law.", r"$(A\cap B)^c=A^c\cup B^c$.",
      r"Negate ``it is raining and cold''.", r"It is not raining or it is not cold (or both).")

    # Q predicate logic
    a(710, r"A predicate $P(x_1,\ldots,x_n)$ is an open sentence with free variables; it becomes a proposition when the variables are instantiated or bound by quantifiers. The universe of discourse is the intended domain. Equality $x=y$ is a binary predicate.",
      r"For $P(x):$ ``$x^2=2$'' on universe $\mathbb{R}$ vs $\mathbb{Q}$, which instantiations are true?",
      r"On $\mathbb{R}$, $P(\sqrt{2})$ is true. On $\mathbb{Q}$, $P(q)$ is false for every rational $q$.",
      r"Is $P(x)$ a proposition?", r"Not until $x$ is specified or quantified.",
      r"Changing the universe silently (``there exists $x$ with $x^2=-1$'' in $\mathbb{R}$ vs $\mathbb{C}$).",
      r"Arity of ``$x$ divides $y$''.", r"Binary.",
      r"Predicate vs function: $f(x)=x^2$ returns a number; $P(x):x^2=2$ returns", r"a truth value.")
    a(711, r"The universal quantifier $\forall x\,P(x)$ means $P(a)$ holds for every $a$ in the universe. Vacuous truth: $\forall x\in\emptyset,\,P(x)$ is true. Restricted form $\forall x\in A,\,P(x)$ means $\forall x\,(x\in A\to P(x))$. To prove $\forall$, take an arbitrary element and argue.",
      r"Truth of $\forall n\in\mathbb{N},\, n\ge 0$ and of $\forall n\in\mathbb{N},\, n\ge 2$.",
      r"True; false (counterexample $n=0$ or $1$, depending on whether $0\in\mathbb{N}$).",
      r"$\forall x\in\emptyset,\, x=x$ is", r"true (vacuous).",
      r"Proving $\forall$ by checking a few examples, or using a specific $x$ that was not arbitrary.",
      r"Negation of $\forall x\,P(x)$.", r"$\exists x\,\neg P(x)$.",
      r"To disprove $\forall n,\, n^2>n$ over $\mathbb{N}$, give", r"a counterexample, e.g. $n=1$ if $1\in\mathbb{N}$, or $n=0$.")
    a(712, r"The existential quantifier $\exists x\,P(x)$ means $P(a)$ holds for at least one $a$ in the universe. A witness is such an $a$. $\exists x\in A,\,P(x)$ means $\exists x\,(x\in A\wedge P(x))$. Uniqueness $\exists! x$ means existence plus uniqueness.",
      r"Give a witness for $\exists x\in\mathbb{Z},\, x^2=4$ and decide $\exists x\in\mathbb{Q},\, x^2=2$.",
      r"Witness $x=2$ (or $-2$). The second is false.",
      r"$\exists x\in\emptyset,\, P(x)$ is", r"false.",
      r"Confusing $\exists$ with $\forall$, or thinking a constructive witness is required in classical logic (nonconstructive existence is allowed).",
      r"Does $\exists n\in\mathbb{N},\, n^2=n$ hold?", r"Yes: $n=0$ or $1$.",
      r"Translate ``some primes are even''.", r"$\exists p\,(P(p)\wedge E(p))$, witness $2$.")
    a(713, r"Negating quantifiers: $\neg\forall x\,P(x)\equiv\exists x\,\neg P(x)$ and $\neg\exists x\,P(x)\equiv\forall x\,\neg P(x)$. Nested: $\neg\forall x\exists y\,R(x,y)\equiv\exists x\forall y\,\neg R(x,y)$. Push $\neg$ inward, flipping each quantifier, until it hits the matrix.",
      r"Negate ``every continuous function on $[0,1]$ is bounded'' as a quantified statement.",
      r"There exists a continuous $f:[0,1]\to\mathbb{R}$ that is unbounded. (This negation is false by EVT; the original is true.)",
      r"$\neg\exists x\forall y,\, x\le y$ over $\mathbb{R}$ becomes", r"$\forall x\exists y,\, y<x$ (no least real).",
      r"Stopping after flipping only the first quantifier, or turning $\forall$ into $\exists$ without negating the predicate.",
      r"Negate $\forall\varepsilon>0\,\exists N\,\forall n\ge N,\, |a_n|<\varepsilon$.", r"$\exists\varepsilon>0\,\forall N\,\exists n\ge N,\, |a_n|\ge\varepsilon$.",
      r"``Not all swans are white'' means", r"there exists a nonwhite swan, not ``all swans are nonwhite''.")
    a(714, r"Order of nested quantifiers matters: $\forall x\exists y\, P(x,y)$ allows $y$ to depend on $x$; $\exists y\forall x\, P(x,y)$ demands a single $y$ working for all $x$. Convergence is $\forall\varepsilon>0\,\exists N\,\forall n\ge N$. Swapping $\forall\varepsilon$ with $\exists N$ yields a much stronger ``$N$ independent of $\varepsilon$'' statement.",
      r"Compare $\forall x\in\mathbb{R}\,\exists y,\, y>x$ with $\exists y\forall x,\, y>x$.",
      r"The first is true (take $y=x+1$). The second is false (no real larger than every real).",
      r"In $a_n\to 0$, may $N$ depend on $\varepsilon$?", r"Yes: that is $\forall\varepsilon\exists N$. It may not depend on $n$.",
      r"Illegally pulling $\exists$ in front of $\forall$ (``there is $N$ for every $\varepsilon$'' misread as independent of $\varepsilon$).",
      r"$\forall\varepsilon>0\,\exists N,\, 1/N<\varepsilon$ is Archimedes. $\exists N\forall\varepsilon>0,\, 1/N<\varepsilon$ would mean", r"$1/N=0$, impossible.",
      r"Continuity vs uniform continuity in quantifiers.", r"Cont: $\forall a\forall\varepsilon\exists\delta\forall x$. Uniform: $\forall\varepsilon\exists\delta\forall a\forall x$ ($\delta$ independent of $a$).")
    a(715, r"$P$ is sufficient for $Q$ when $P\to Q$. $P$ is necessary for $Q$ when $Q\to P$ (i.e. $Q$ cannot hold without $P$). $P$ is necessary and sufficient for $Q$ when $P\leftrightarrow Q$. ``Only if'' marks necessity; ``if'' marks sufficiency.",
      r"``$n$ divisible by $4$'' vs ``$n$ even'': which is necessary, which sufficient?",
      r"Divisible by $4$ is sufficient for even, not necessary. Even is necessary for divisible by $4$, not sufficient.",
      r"Differentiability is sufficient for continuity: true?", r"True. It is not necessary ($|x|$).",
      r"Reversing necessary and sufficient, or reading ``only if'' as ``if''.",
      r"``$f$ continuous on $[a,b]$'' is sufficient for integrability: true?", r"True. Not necessary (jumps allowed).",
      r"Translate ``$x>0$ only if $x^2>0$''.", r"$x>0\to x^2>0$ (necessary condition $x^2>0$ for $x>0$).")

    # Q proof methods
    a(716, r"A direct proof of $P\to Q$ assumes $P$ and, using definitions and known theorems, deduces $Q$. Algebraic identities, chasing elements in sets, and unfolding definitions are typical. Keep the hypothesis in play until the conclusion appears.",
      r"Prove directly: the product of two even integers is even.",
      r"Let $m=2k$, $n=2\ell$. Then $mn=4k\ell=2(2k\ell)$, even.",
      r"Direct proof of ``odd times odd is odd'': write", r"$(2k+1)(2\ell+1)=2(\cdots)+1$.",
      r"Inserting an unjustified step that secretly uses the conclusion (circularity).",
      r"Prove: if $a\mid b$ and $b\mid c$ then $a\mid c$.", r"$b=aq$, $c=br=aqr$, so $a\mid c$.",
      r"To prove $A\subset B$ directly, take $x\in A$ and show", r"$x\in B$.")
    a(717, r"A proof by contrapositive establishes $P\to Q$ by proving $\neg Q\to\neg P$. Use it when the negated conclusion is easier to manipulate (parity, non-membership, failure of an inequality). It is not a proof of the converse.",
      r"Prove: if $n^2$ is even then $n$ is even, by contrapositive.",
      r"Assume $n$ odd, $n=2k+1$. Then $n^2=4k^2+4k+1$ odd. So $n$ odd $\Rightarrow$ $n^2$ odd.",
      r"Contrapositive of ``if $f'(a)$ exists then $f$ is continuous at $a$''.", r"If $f$ is discontinuous at $a$, then $f'(a)$ does not exist.",
      r"Negating incorrectly (``$n$ not even'' written as ``$n$ negative'') or proving the converse instead.",
      r"Why is this better than contradiction for the even-square lemma?", r"The odd case is an explicit computation; no extra false assumption to discharge.",
      r"Prove: if $A\cap B=\emptyset$ then $A\subset B^c$, by contrapositive.", r"If $A\not\subset B^c$, some $x\in A\cap B$.")
    a(718, r"Proof by contradiction: to prove $P$, assume $\neg P$ and derive a falsehood (e.g. $1=0$, or a previously known theorem's negation). Classic: $\sqrt{2}$ is irrational. Unlike contrapositive, there is no implication being rewritten; the whole claim is at stake.",
      r"Prove $\sqrt{2}$ is irrational.",
      r"If $\sqrt{2}=p/q$ in lowest terms, then $p^2=2q^2$, so $p$ even, $p=2k$, then $q^2=2k^2$, $q$ even, contradicting lowest terms.",
      r"Assume there are finitely many primes, Euclid-style, and derive", r"a new prime $N=p_1\cdots p_k+1$ (more carefully: a prime factor of $N$ not in the list).",
      r"Assuming extra structure not in $\neg P$, or stopping at a surprising but possible statement.",
      r"Prove there is no largest integer by contradiction.", r"If $N$ is largest, $N+1>N$ is an integer.",
      r"Contradiction vs contrapositive for $P\to Q$.", r"Contradiction assumes $P$ and $\neg Q$; contrapositive assumes only $\neg Q$.")
    a(719, r"Proof by cases splits on a partition of the universe (even/odd, sign of $x$, $n\bmod 3$, $x\in A$ vs not). Each case must be exhaustive and mutually exclusive enough to cover all possibilities. The conclusion must be the same in every case, or pieced together carefully.",
      r"Prove $n^2-n$ is even for all $n\in\mathbb{Z}$ by cases.",
      r"If $n=2k$, then $n(n-1)=2k(2k-1)$ even. If $n=2k+1$, then $n-1=2k$, product even. (Consecutive integers.)",
      r"To prove $|x|\ge x$ for all real $x$, cases are", r"$x\ge 0$ ($|x|=x$) and $x<0$ ($|x|=-x>x$).",
      r"Missing a case (zero, or overlapping moduli) or using overlapping cases with incompatible substitutions.",
      r"Prove $x^2\ge 0$ by cases on the sign of $x$.", r"Nonnegative: square of square root or $x\cdot x$. Negative: $(-x)^2$ with $-x>0$. Or $(x-0)^2$.",
      r"Cases $n\equiv 0,1,2\pmod{3}$ exhaust", r"all integers.")
    a(720, r"A single counterexample disproves a universal claim $\forall x\,P(x)$. It does not disprove an existential claim. To show a construction always works, examples are not enough. Check the exact quantifiers before hunting counterexamples.",
      r"Disprove: every injective $f:\mathbb{N}\to\mathbb{N}$ is surjective.",
      r"Counterexample $f(n)=n+1$: injective, misses $1$ (or $0$).",
      r"Does $n\mapsto 2n$ on $\mathbb{N}$ disprove ``every injective self-map is surjective''?", r"Yes: injective, image the evens.",
      r"Offering a counterexample to an existential statement, or an example as a proof of $\forall$.",
      r"Disprove ``if $f'>0$ everywhere then $f$ is unbounded''.", r"$\arctan$: $f'>0$ on $\mathbb{R}$ but range $(-\pi/2,\pi/2)$.",
      r"One counterexample to $\forall n,\, 2^n>n^2$ over $\mathbb{N}$.", r"$n=2$: $4\not>4$. Also $n=3,4$.")
    a(721, r"Existence proofs: constructive (exhibit a witness) or nonconstructive (show that nonexistence is impossible, often via IVT, pigeonhole, or contradiction). Classical logic allows the latter. $\exists x,\, x^2=2$ in $\mathbb{R}$ follows from IVT or completeness, without writing digits of $\sqrt{2}$.",
      r"Show there exist irrationals $a,b$ with $a^b$ rational, possibly nonconstructively.",
      r"Let $\alpha=\sqrt{2}^{\sqrt{2}}$. If $\alpha$ is rational, done ($a=b=\sqrt{2}$). If $\alpha$ is irrational, then $\alpha^{\sqrt{2}}=2$ with both exponents/bases irrational. (Gelfond--Schneider actually makes $\alpha$ transcendental.)",
      r"IVT existence of a root of $x^3-x-1$ on $[1,2]$ is", r"nonconstructive (unless one also produces a decimal).",
      r"Claiming existence after showing a set is nonempty in a way that uses AC without comment, when an explicit witness is asked.",
      r"Constructive witness that $\exists n,\, n^2=n$.", r"$n=0$ or $n=1$.",
      r"Pigeonhole: among $13$ people, two share a", r"birth month (existence without naming them).")
    a(722, r"A uniqueness proof has two parts: existence, and if $a,b$ both satisfy the property then $a=b$. Typical tools: subtract equations, apply a cancellation law, or note that a strictly monotone function hits a value at most once. ``There exists a unique'' is $\exists!$.",
      r"Prove the additive identity in a group is unique.",
      r"If $e$ and $e'$ are identities, $e=e\cdot e'=e'$.",
      r"Uniqueness of $\sup S$ for nonempty $S\subset\mathbb{R}$ bounded above: why?", r"The least upper bound is unique: if $M,M'$ are both least, $M\le M'$ and $M'\le M$.",
      r"Proving uniqueness without existence (or vice versa) when the problem asked for $\exists!$.",
      r"At most one root of $e^x=2$: reason.", r"$e^x$ is strictly increasing, hence injective.",
      r"Division algorithm: uniqueness of $q,r$ with $a=bq+r$, $0\le r<b$. Idea.", r"If two remainders, their difference is a multiple of $b$ smaller than $b$, hence $0$.")
    a(723, r"Mathematical induction: to prove $P(n)$ for all integers $n\ge n_0$, prove $P(n_0)$ (base) and $\forall k\ge n_0,\, (P(k)\to P(k+1))$ (successor). Equivalent to well-ordering. The inductive hypothesis $P(k)$ is an assumption for that step, not the theorem.",
      r"Prove $\sum_{k=1}^n k=n(n+1)/2$ by induction.",
      r"Base $n=1$: $1=1$. If true for $k$, then $\sum^{k+1}=k(k+1)/2+(k+1)=(k+1)(k+2)/2$.",
      r"Base case can start at $n_0=0$ or $n=2$ if needed: true?", r"True: the statement is only claimed from $n_0$ on.",
      r"Using $P(k+1)$ inside the proof of $P(k+1)$, or skipping a valid base (e.g. all horses the same color).",
      r"Inductive step for $2^n\ge n+1$, $n\ge 0$.", r"$2^{k+1}=2\cdot 2^k\ge 2(k+1)=2k+2\ge k+2$.",
      r"Does induction prove $P(n)$ for real $n$?", r"No: only along the integers from the base.")
    a(724, r"Strong induction: assume $P(j)$ for all $n_0\le j\le k$ (or all $j<n$) and prove $P(k+1)$ (or $P(n)$). Equivalent to ordinary induction. Use it when the predecessor that matters is not $n-1$ (prime factors, Fibonacci, postage).",
      r"Prove every integer $n\ge 2$ has a prime factor, by strong induction.",
      r"If $n$ is prime, done. If $n=ab$ with $1<a,b<n$, the inductive hypothesis supplies a prime factor of $a$, hence of $n$.",
      r"Postage: $4$ and $5$ cents make every $n\ge N$ for $N=$", r"$12$ (check a block of $4$ consecutive, then add $4$).",
      r"Using strong induction but only invoking $P(k)$, which is ordinary induction in disguise and may be insufficient.",
      r"Fibonacci $F_n\le 2^{n-1}$: the step uses", r"$F_{k+1}=F_k+F_{k-1}$, hence two previous cases.",
      r"Ordinary vs strong: logically", r"equivalent over $\mathbb{N}$.")
    a(725, r"Well-ordering principle: every nonempty subset of $\mathbb{N}$ has a least element. Equivalent to induction. Infinite descent is the contrapositive: there is no infinite strictly decreasing sequence of naturals. Used in the division algorithm and unique factorization.",
      r"Prove the division algorithm's existence via well-ordering.",
      r"The set of nonnegative remainders $\{a-bq:q\in\mathbb{Z},\, a-bq\ge 0\}$ is a nonempty subset of $\mathbb{N}\cup\{0\}$, hence has a least $r$, and $r<b$ else subtract one more $b$.",
      r"Infinite descent proof that $\sqrt{2}$ is irrational recasts Euclid as", r"an infinite decreasing sequence of positive integer denominators.",
      r"Applying well-ordering to $\mathbb{Z}$ or $(0,1)\cap\mathbb{Q}$ (no least element).",
      r"Does $\mathbb{Z}$ satisfy well-ordering under the usual $\le$?", r"No: the negatives have no least element; $\mathbb{Z}_{<0}$ is nonempty with no minimum.",
      r"Least element of $\{n\in\mathbb{N}:n>5\}$.", r"$6$ (if $\mathbb{N}$ starts at $1$).")

    # Q set theory
    a(726, r"Set notation: roster $\{1,2,3\}$, comprehension $\{x\in A:P(x)\}$, empty set $\emptyset$. Extensionality: sets are equal iff they have the same elements. Order and repetition in roster notation are irrelevant: $\{1,1,2\}=\{2,1\}$.",
      r"Simplify $\{n\in\mathbb{Z}:n^2=n\}$ and $\{x\in\mathbb{R}:x^2<0\}$.",
      r"$\{0,1\}$; $\emptyset$.",
      r"$\{1,2,3\}=\{3,2,1,1\}$?", r"Yes.",
      r"Writing $\{x,x\}$ as a two-element set, or using $=$ between a set and an element.",
      r"Is $\{\emptyset\}$ equal to $\emptyset$?", r"No: the first has one element.",
      r"Comprehension $\{n\in\mathbb{N}:n\text{ even}\}$.", r"The even naturals.")
    a(727, r"Membership $x\in A$ means $x$ is an element of $A$. It is not the same as $\subset$. Thus $1\in\{1,2\}$, $\{1\}\subset\{1,2\}$, and $1\notin\{\{1\}\}$, while $\{1\}\in\{\{1\}\}$. $\emptyset$ has no elements. Foundation / well-foundedness forbids $x\in x$ in ZFC.",
      r"Which are true: $2\in\{1,2,3\}$, $\{2\}\in\{1,2,3\}$, $\{2\}\subset\{1,2,3\}$, $\emptyset\in\{\emptyset\}$?",
      r"True, false, true, true.",
      r"Is $\emptyset\in\emptyset$?", r"No.",
      r"Writing $x\subset A$ when $x$ is an element, especially for numbers vs singletons.",
      r"$a\in\{a,b\}$ always?", r"Yes, by roster meaning.",
      r"Is $\mathbb{N}\in\mathbb{Z}$?", r"No: $\mathbb{N}$ is a set of integers, not an integer.")
    a(728, r"$A\subset B$ (or $A\subseteq B$) means every element of $A$ is an element of $B$. Always $A\subset A$ and $\emptyset\subset A$. $A=B$ iff $A\subset B$ and $B\subset A$. Transitive: $A\subset B\subset C$ implies $A\subset C$. Proofs proceed by taking an arbitrary $x\in A$.",
      r"Prove $\{n\in\mathbb{Z}:4\mid n\}\subset\{n\in\mathbb{Z}:2\mid n\}$.",
      r"If $4\mid n$ then $n=4k=2(2k)$, so $2\mid n$.",
      r"Is $\mathbb{N}\subset\mathbb{Z}\subset\mathbb{Q}\subset\mathbb{R}$?", r"Yes (with the standard identifications).",
      r"Proving subset by an example, or mixing $\in$ with $\subset$.",
      r"Does $A\subset B$ imply $|A|\le|B|$?", r"Yes (the inclusion is an injection).",
      r"To prove $A=B$, show", r"both inclusions.")
    a(729, r"A proper subset $A\subsetneq B$ (sometimes written $A\subset B$ by authors who use $\subseteq$ for the weak relation) means $A\subset B$ and $A\neq B$, so some element of $B$ lies outside $A$. $\mathbb{N}\subsetneq\mathbb{Z}\subsetneq\mathbb{Q}\subsetneq\mathbb{R}$. Every set has itself as a subset, not always proper.",
      r"Is $\{1,2\}$ a proper subset of $\{1,2,3\}$? Of $\{1,2\}$?",
      r"Yes; no.",
      r"Does every nonempty set have a proper subset?", r"Yes: at least $\emptyset$, unless one excludes $\emptyset$ by convention; $\emptyset$ itself has no proper subset.",
      r"Using $\subset$ without checking the author's convention on whether equality is allowed.",
      r"$\mathbb{Z}\subsetneq\mathbb{Q}$ because", r"e.g. $1/2\notin\mathbb{Z}$.",
      r"Is $\emptyset\subsetneq\{0\}$?", r"Yes.")
    a(730, r"Union $A\cup B=\{x:x\in A\text{ or }x\in B\}$. Associative, commutative, $A\cup\emptyset=A$, $A\cup A=A$, $A\subset A\cup B$. Arbitrary unions $\bigcup_{i\in I}A_i$. Distributive over intersection.",
      r"Compute $\{1,2,3\}\cup\{3,4\}$ and $\bigcup_{n=1}^\infty (0,1-1/n)$.",
      r"$\{1,2,3,4\}$; $(0,1)$. (Each $x\in(0,1)$ lies in all sufficiently large intervals.)",
      r"$A\cup B=A$ iff", r"$B\subset A$.",
      r"Dropping elements that appear in both (as if union were disjoint union).",
      r"$\bigcup_{n\in\mathbb{Z}}[n,n+1]$.", r"$\mathbb{R}$.",
      r"$A\subset B$ implies $A\cup C\subset$", r"$B\cup C$.")
    a(731, r"Intersection $A\cap B=\{x:x\in A\text{ and }x\in B\}$. Associative, commutative, $A\cap\emptyset=\emptyset$, $A\cap A=A$, $A\cap B\subset A$. Disjoint means $A\cap B=\emptyset$. Distributes over union. Arbitrary intersections $\bigcap_{i\in I}A_i$ may be empty even if each finite intersection is not.",
      r"Compute $\{1,2,3\}\cap\{3,4\}$ and $\bigcap_{n=1}^\infty (0,1+1/n)$.",
      r"$\{3\}$; $(0,1]$.",
      r"Sets $A,B$ are disjoint iff", r"$A\cap B=\emptyset$.",
      r"Assuming an infinite nested family of nonempty sets has nonempty intersection (need compactness / nested closed intervals).",
      r"$\bigcap_n (0,1/n)$.", r"$\emptyset$.",
      r"$A\cap B=A$ iff", r"$A\subset B$.")
    a(732, r"Set difference $A\setminus B=\{x\in A:x\notin B\}=A\cap B^c$. Not commutative. $A\setminus A=\emptyset$, $A\setminus\emptyset=A$. Symmetric difference $A\Delta B=(A\setminus B)\cup(B\setminus A)$ is the set where the characteristic functions differ.",
      r"Compute $\{1,2,3\}\setminus\{2,3,4\}$ and $\{2,3,4\}\setminus\{1,2,3\}$.",
      r"$\{1\}$; $\{4\}$.",
      r"$(A\setminus B)\cup(A\cap B)$ equals", r"$A$.",
      r"Treating $\setminus$ as arithmetic minus of cardinalities without checking overlap.",
      r"$A\setminus B=A$ iff", r"$A\cap B=\emptyset$.",
      r"Symmetric difference of $[0,2]$ and $[1,3]$ in $\mathbb{R}$.", r"$[0,1)\cup(2,3]$ (or with endpoints depending on closedness: $[0,1)\cup(2,3]$ if both closed).")
    a(733, r"The complement of $A$ relative to a universe $X$ is $A^c=X\setminus A$. Then $(A^c)^c=A$, $A\cup A^c=X$, $A\cap A^c=\emptyset$. De Morgan: $(A\cup B)^c=A^c\cap B^c$. Complement depends on the ambient $X$.",
      r"If $X=\mathbb{Z}$ and $A$ is the even integers, what is $A^c$? If instead $X=\mathbb{R}$?",
      r"The odd integers; $\mathbb{R}\setminus 2\mathbb{Z}$, which includes odds, non-integers, etc.",
      r"$(A\cap B)^c$ equals", r"$A^c\cup B^c$.",
      r"Taking complements in two different universes in the same argument.",
      r"Complement of $(0,1)$ in $\mathbb{R}$.", r"$(-\infty,0]\cup[1,\infty)$.",
      r"Is $\emptyset^c=X$ and $X^c=\emptyset$?", r"Yes.")
    a(734, r"The Cartesian product $A\times B=\{(a,b):a\in A,\, b\in B\}$. Ordered pairs satisfy $(a,b)=(c,d)$ iff $a=c$ and $b=d$. $|A\times B|=|A|\,|B|$ for finite sets. $A\times\emptyset=\emptyset$. Not commutative: $A\times B\neq B\times A$ in general as sets of pairs. $\mathbb{R}\times\mathbb{R}=\mathbb{R}^2$.",
      r"List $\{1,2\}\times\{a,b\}$ and decide whether $(1,a)=(a,1)$.",
      r"$\{(1,a),(1,b),(2,a),(2,b)\}$. No, unless $1=a$.",
      r"$A\times B=\emptyset$ iff", r"$A=\emptyset$ or $B=\emptyset$.",
      r"Treating $(a,b)$ as $\{a,b\}$, which collapses order and repeats.",
      r"$|\{1,2,3\}\times\{0,1\}|$.", r"$6$.",
      r"Is $\mathbb{N}\times\{0\}\cong\mathbb{N}$ as sets?", r"Yes: $(n,0)\mapsto n$ is a bijection.")
    a(735, r"The power set $\mathcal{P}(A)=\{B:B\subset A\}$ has $2^{|A|}$ elements when $A$ is finite. Always $\emptyset,A\in\mathcal{P}(A)$. $A\subset B$ implies $\mathcal{P}(A)\subset\mathcal{P}(B)$. Cantor's theorem: there is no surjection $A\to\mathcal{P}(A)$, so $|A|<|\mathcal{P}(A)|$.",
      r"List $\mathcal{P}(\{1,2\})$ and compute $|\mathcal{P}(\{1,2,3\})|$.",
      r"$\{\emptyset,\{1\},\{2\},\{1,2\}\}$; $8$.",
      r"$|\mathcal{P}(\emptyset)|$ equals", r"$1$, because $\mathcal{P}(\emptyset)=\{\emptyset\}$.",
      r"Counting only nonempty subsets, or writing $n^2$ instead of $2^n$.",
      r"Is $\{1\}\in\mathcal{P}(\{1,2\})$? Is $\{1\}\subset\mathcal{P}(\{1,2\})$?", r"Yes; no. The subset claim would require $1\in\mathcal{P}(\{1,2\})$, but $1$ is not a subset of $\{1,2\}$.",
      r"Cantor: $|\mathbb{N}|$ vs $|\mathcal{P}(\mathbb{N})|$.", r"Strictly smaller; $\mathcal{P}(\mathbb{N})$ is uncountable.")
    a(736, r"A partition of $X$ is a family of nonempty pairwise disjoint subsets whose union is $X$. Equivalence classes of an equivalence relation form a partition. Fibers $f^{-1}(\{y\})$ of a surjection partition the domain. $\{\{1,2\},\{2,3\}\}$ is not a partition of $\{1,2,3\}$.",
      r"Do the residue classes $\overline{0},\overline{1},\overline{2}$ modulo $3$ partition $\mathbb{Z}$?",
      r"Yes: nonempty, disjoint, union $\mathbb{Z}$.",
      r"Is $\{\{1\},\{2,3\},\{3\}\}$ a partition of $\{1,2,3\}$?", r"No: $3$ appears twice, classes not disjoint.",
      r"Allowing the empty set as a block, or overlapping blocks.",
      r"The even/odd partition of $\mathbb{Z}$ has how many blocks?", r"$2$.",
      r"Can a partition of an infinite set have infinitely many blocks?", r"Yes: $\{\{n\}:n\in\mathbb{Z}\}$ of $\mathbb{Z}$.")
    a(737, r"A relation on $A$ is a subset $R\subset A\times A$; one writes $aRb$ for $(a,b)\in R$. Reflexive: $\forall a,\, aRa$. Symmetric: $aRb\Rightarrow bRa$. Transitive: $aRb$ and $bRc\Rightarrow aRc$. Antisymmetric: $aRb$ and $bRa\Rightarrow a=b$. $<$ on $\mathbb{R}$ is transitive, not reflexive.",
      r"Classify $<$ and $\le$ on $\mathbb{R}$ by the four properties.",
      r"$<$ is transitive, irreflexive, not symmetric. $\le$ is reflexive, antisymmetric, transitive (a partial order), not symmetric.",
      r"The empty relation on a nonempty set is reflexive?", r"No: $aRa$ fails.",
      r"Checking transitivity only on a chain of three distinct elements and missing $aRa$ loops.",
      r"Is ``divides'' on $\mathbb{N}$ symmetric?", r"No: $2\mid 4$ but $4\nmid 2$.",
      r"Equality on any set is", r"an equivalence relation (and a partial order).")
    a(738, r"An equivalence relation is reflexive, symmetric, and transitive. Standard examples: equality; $a\equiv b\pmod n$; similarity of matrices; ``has the same cardinality''. An equivalence relation is precisely the relation of belonging to the same block of a partition.",
      r"Show $a\sim b$ iff $a-b\in\mathbb{Z}$ is an equivalence relation on $\mathbb{R}$.",
      r"Reflexive: $0\in\mathbb{Z}$. Symmetric: $b-a=-(a-b)$. Transitive: integers form a group under addition.",
      r"Is ``differ by a multiple of $2\pi$'' an equivalence on $\mathbb{R}$?", r"Yes: it is congruence modulo $2\pi$.",
      r"Dropping reflexivity (``parallel lines'' if a line is not declared parallel to itself).",
      r"Is $x\sim y$ iff $xy>0$ an equivalence on $\mathbb{R}\setminus\{0\}$?", r"Yes: same (strict) sign. On $\mathbb{R}$ it fails reflexivity at $0$.",
      r"Congruence modulo $n$ on $\mathbb{Z}$ is an equivalence: the three properties come from", r"divisibility of differences.")
    a(739, r"The equivalence class of $a$ is $[a]=\{x:x\sim a\}$. Then $a\sim b$ iff $[a]=[b]$, and distinct classes are disjoint. The quotient $A/{\sim}$ is the set of classes. In $\mathbb{Z}/n\mathbb{Z}$ there are $n$ classes, written $\overline{0},\ldots,\overline{n-1}$.",
      r"For $a\equiv b\pmod 2$ on $\mathbb{Z}$, describe $[0]$ and $[1]$.",
      r"Evens; odds. These are the only two classes.",
      r"$[a]=[b]$ iff", r"$a\sim b$.",
      r"Thinking two classes can overlap in some but not all elements (they cannot).",
      r"How many distinct classes for ``same fractional part'' on $\mathbb{R}$ (i.e. $x-y\in\mathbb{Z}$)?", r"One per residue in $[0,1)$: uncountably many, parametrized by $[0,1)$.",
      r"The quotient map $a\mapsto[a]$ is", r"a surjection $A\to A/{\sim}$.")
    a(740, r"A partial order is a reflexive, antisymmetric, transitive relation. Examples: $\le$ on $\mathbb{R}$; $\subset$ on $\mathcal{P}(X)$; divisibility $\mid$ on $\mathbb{N}$. Incomparable elements may exist: $2\nmid 3$ and $3\nmid 2$. Hasse diagrams display covering relations.",
      r"Why is divisibility on $\mathbb{N}$ a partial order but not a total order?",
      r"Reflexive, antisymmetric ($a\mid b$ and $b\mid a\Rightarrow a=b$ for positive integers), transitive. Not total: $2$ and $3$ are incomparable.",
      r"Is $\subset$ on $\mathcal{P}(\{1,2\})$ a partial order?", r"Yes. $\{1\}$ and $\{2\}$ are incomparable.",
      r"Requiring comparability of every pair (that is a total order), or dropping antisymmetry (preorders).",
      r"Maximal vs maximum in a poset.", r"Maximum is comparable to and $\ge$ every element; maximal means nothing is strictly above it.",
      r"Least element of $(\mathcal{P}(X),\subset)$.", r"$\emptyset$.")
    a(741, r"A total (linear) order is a partial order in which every two elements are comparable: $a\le b$ or $b\le a$. $(\mathbb{R},\le)$ and $(\mathbb{N},\le)$ are total. Divisibility on $\mathbb{N}$ is not. Lexicographic order on $\mathbb{R}^2$ is total. A well-order is a total order in which every nonempty subset has a least element.",
      r"Is lexicographic order on $\{1,2\}\times\{1,2\}$ total? Name the least and greatest pairs.",
      r"Yes. Least $(1,1)$, greatest $(2,2)$, with $(1,2)<(2,1)$.",
      r"$(\mathbb{N},\mid)$ is total?", r"No.",
      r"Calling any partial order total, or confusing well-order with total order ($\mathbb{Z}$ is total not well-ordered).",
      r"Usual order on $\mathbb{Z}$: total? well-order?", r"Total yes; well-order no.",
      r"Dictionary order on words of a fixed length over an alphabet is", r"a total order.")

    # Q functions & cardinality
    a(742, r"$f:A\to B$ is injective if $f(x)=f(y)\Rightarrow x=y$ (equivalently, distinct inputs give distinct outputs). Real functions: horizontal line test; strictly monotone functions are injective. Injective maps are left-cancellable. $|f(A)|=|A|$.",
      r"Is $f(x)=x^2$ injective on $\mathbb{R}$? On $[0,\infty)$? Is $n\mapsto n+1$ injective on $\mathbb{N}$?",
      r"No; yes; yes.",
      r"$f:\mathbb{R}\to\mathbb{R}$, $f(x)=e^x$, injective?", r"Yes, strictly increasing.",
      r"Checking $f(x)=f(-x)$ only at one point, or confusing injective with surjective.",
      r"Prove $f(x)=3x+1$ is injective.", r"$3x+1=3y+1\Rightarrow x=y$.",
      r"Injection $A\to A$ on a finite set is automatically", r"surjective (hence bijective).")
    a(743, r"$f:A\to B$ is surjective if every $b\in B$ is $f(a)$ for some $a$ (range equals codomain). Changing the codomain can create or destroy surjectivity without changing the formula. Right-cancellable. For finite sets, $|A|\ge|B|$ is necessary.",
      r"Is $e^x:\mathbb{R}\to\mathbb{R}$ surjective? $\mathbb{R}\to(0,\infty)$?",
      r"No; yes.",
      r"$x\mapsto x^3:\mathbb{R}\to\mathbb{R}$ is", r"surjective (and injective).",
      r"Forgetting the declared codomain (``$x^2$ is onto'' without saying onto $[0,\infty)$).",
      r"Is $\sin:\mathbb{R}\to[-1,1]$ surjective?", r"Yes. Onto $\mathbb{R}$: no.",
      r"A surjection $A\to A$ on a finite set is automatically", r"injective.")
    a(744, r"A bijection is an injective surjection; equivalently, $f$ has a two-sided inverse. Then $|A|=|B|$. Schr\"oder--Bernstein: injections $A\to B$ and $B\to A$ imply a bijection $A\leftrightarrow B$. Finite sets: bijections are the permutations.",
      r"Exhibit a bijection $(-\pi/2,\pi/2)\to\mathbb{R}$.",
      r"$\tan$. Inverse $\arctan$.",
      r"If $|A|=|B|$ finite and $f:A\to B$ is injective, then $f$ is", r"bijective.",
      r"Producing two injections and not invoking Schr\"oder--Bernstein when a bijection is required, or claiming $n\mapsto n+1$ is a bijection $\mathbb{N}\to\mathbb{N}$.",
      r"Bijection $\mathbb{N}\to\mathbb{Z}$: sketch.", r"Enumerate $0,1,-1,2,-2,\ldots$.",
      r"Identity map is a bijection: true?", r"True.")
    a(745, r"Composition $(g\circ f)(x)=g(f(x))$ requires $\mathrm{ran} f\subset\mathrm{dom}\, g$. Associative, not commutative. $g\circ f$ injective if both are; surjective if both are. If $g\circ f$ is injective then $f$ is injective; if $g\circ f$ is surjective then $g$ is surjective. $(g\circ f)^{-1}=f^{-1}\circ g^{-1}$ for bijections.",
      r"For $f(x)=x+1$ and $g(x)=2x$ on $\mathbb{R}$, compute $g\circ f$ and $f\circ g$.",
      r"$2x+2$; $2x+1$. Not equal.",
      r"If $g\circ f$ is injective, which of $f,g$ must be injective?", r"$f$ must; $g$ need not (on its whole domain).",
      r"Reversing the order of composition, especially for inverses.",
      r"Associativity: $(h\circ g)\circ f$ vs $h\circ(g\circ f)$.", r"Equal.",
      r"$g\circ f$ surjective implies", r"$g$ is surjective.")
    a(746, r"If $f:A\to B$ is bijective, the inverse $f^{-1}:B\to A$ satisfies $f^{-1}(f(a))=a$ and $f(f^{-1}(b))=b$. The graph is the reflection of the graph of $f$ across $y=x$. For differentiable $f$ with $f'\neq 0$, $(f^{-1})'(b)=1/f'(f^{-1}(b))$. Preimages $f^{-1}(T)$ exist even when $f$ is not invertible.",
      r"Find the inverse of $f(x)=2x+3$ and of $f(x)=e^x$ (as $\mathbb{R}\to(0,\infty)$).",
      r"$(y-3)/2$; $\ln$.",
      r"Notation $f^{-1}(T)$ for $T$ a set requires invertibility of $f$?", r"No: it denotes the preimage.",
      r"Writing $f^{-1}=1/f$, or reflecting across $y=0$ instead of $y=x$.",
      r"Inverse of $\tan:(-\pi/2,\pi/2)\to\mathbb{R}$.", r"$\arctan$.",
      r"If $f$ is not injective, can a two-sided inverse exist?", r"No.")
    a(747, r"A set is countable if it is finite or in bijection with a subset of $\mathbb{N}$ (equivalently: there is an injection into $\mathbb{N}$). Countable unions of countable sets are countable; finite products of countable sets are countable. $\mathbb{N}$, $\mathbb{Z}$, $\mathbb{Q}$, and the algebraic numbers are countable.",
      r"Why is $\mathbb{Z}$ countable? Why is $\mathbb{Q}$ countable?",
      r"$\mathbb{Z}$ lists as $0,1,-1,2,-2,\ldots$. $\mathbb{Q}$ lists by diagonals of $\mathbb{Z}\times\mathbb{N}$ (lowest terms), skipping repeats.",
      r"A subset of a countable set is", r"countable.",
      r"Claiming $\mathbb{Q}$ is uncountable because it is dense, or that ``infinite'' means countable.",
      r"Is a countable union of finite sets countable?", r"Yes.",
      r"The set of finite binary strings is", r"countable (union over length).")
    a(748, r"A set is countably infinite (denumerable) if it is in bijection with $\mathbb{N}$, i.e. cardinality $\aleph_0$. Hilbert's hotel: $\aleph_0+1=\aleph_0$ and $\aleph_0+\aleph_0=\aleph_0$. Cantor pairing: $\mathbb{N}\times\mathbb{N}\cong\mathbb{N}$. $\mathbb{Q}\cong\mathbb{N}$. An infinite subset of a countably infinite set is countably infinite.",
      r"Give an explicit bijection $\mathbb{N}\times\mathbb{N}\to\mathbb{N}$ (or an injection both ways).",
      r"Pairing $(m,n)\mapsto 2^m(2n+1)-1$, or diagonal enumeration. Injections: $(m,n)\mapsto 2^m 3^n$ and $k\mapsto(k,1)$.",
      r"Hilbert hotel: a hotel with $\aleph_0$ full rooms can still accommodate one more guest by", r"$n\mapsto n+1$, freeing room $1$.",
      r"Calling $\mathbb{R}$ countably infinite, or thinking removing one point from $\mathbb{N}$ changes cardinality.",
      r"$|\mathbb{N}|$, $|\mathbb{Z}|$, $|\mathbb{Q}|$ compared.", r"All equal $\aleph_0$.",
      r"Even naturals vs $\mathbb{N}$.", r"Bijection $n\mapsto 2n$; same cardinality.")
    a(749, r"A set is uncountable if it is not countable, i.e. there is no injection into $\mathbb{N}$. $\mathbb{R}$, $[0,1]$, $\mathcal{P}(\mathbb{N})$, $\{0,1\}^{\mathbb{N}}$, and $C[0,1]$ are uncountable. Uncountable sets can have different cardinalities; $|\mathbb{R}|=2^{\aleph_0}=\mathfrak{c}$. Continuum hypothesis ($2^{\aleph_0}=\aleph_1$) is independent of ZFC.",
      r"Deduce that $\mathbb{R}$ is uncountable from the countability of $\mathbb{Q}$ and the existence of irrationals? Why is that insufficient, and what actually works?",
      r"Insufficient: $\mathbb{Q}\cup\{\sqrt{2}\}$ is still countable. Need Cantor's diagonal argument (or $|\mathcal{P}(\mathbb{N})|=2^{\aleph_0}$ and $\mathcal{P}(\mathbb{N})\hookrightarrow\mathbb{R}$).",
      r"$[0,1]$ is uncountable: true?", r"True, in bijection with $\mathbb{R}$ (e.g. via $\tan$ on $(0,1)$ plus junk at endpoints).",
      r"Thinking every uncountable set is in bijection with $\mathbb{R}$.",
      r"Is $\mathbb{R}\setminus\mathbb{Q}$ uncountable?", r"Yes: otherwise $\mathbb{R}$ would be a countable union of countable sets.",
      r"$|\mathcal{P}(\mathbb{N})|$ vs $|\mathbb{N}|$.", r"Strictly larger (Cantor's theorem).")
    a(750, r"Cantor's diagonal argument: if $(x_n)$ were a list of all reals in $(0,1)$, write decimal expansions $x_n=0.d_{n1}d_{n2}\ldots$ and define $e_n\neq d_{nn}$ with $e_n\in\{1,2\}$ (avoiding $0$ and $9$ to dodge dual representations). Then $0.e_1 e_2\ldots$ differs from each $x_n$ in the $n$th place, contradiction. Hence $(0,1)$ is uncountable.",
      r"Given a purported list $0.5000\ldots$, $0.3333\ldots$, $0.1415\ldots$, construct a diagonal number using digits $1$ and $2$.",
      r"First digits $5,3,1$. Choose $e_1=1$ ($\neq 5$), $e_2=1$ ($\neq 3$), $e_3=2$ ($\neq 1$), and continue; the result is not on the list.",
      r"Why avoid digit $9$ in the diagonal construction?", r"So the new number is not a terminating expansion equal to another listing of some $x_n$.",
      r"Diagonalizing only finitely many places, or using binary expansions without care about $0.0111\ldots=0.1000\ldots$.",
      r"The same idea shows $\{0,1\}^{\mathbb{N}}$ is uncountable: the diagonal sequence", r"flips the $n$th bit of the $n$th sequence.",
      r"Does the argument show $|\mathbb{R}|>|\mathbb{N}|$ or merely that one listing fails?", r"It shows every listing fails, hence no bijection with $\mathbb{N}$.")
    a(751, r"Cardinal arithmetic (infinite): $\aleph_0+n=\aleph_0=\aleph_0+\aleph_0=\aleph_0\cdot\aleph_0$. For infinite $\kappa$, $\kappa+\kappa=\kappa$ under AC. $2^{\aleph_0}=\mathfrak{c}=|\mathbb{R}|$, and $\mathfrak{c}+\mathfrak{c}=\mathfrak{c}=\mathfrak{c}\cdot\mathfrak{c}=|\mathbb{R}^n|$. Always $2^\kappa>\kappa$ by Cantor. $|\mathcal{P}(A)|=2^{|A|}$.",
      r"Compute $|\mathbb{Z}|$, $|\mathbb{Q}|$, $|\mathbb{R}|$, $|\mathbb{R}^2|$, $|\mathcal{P}(\mathbb{N})|$.",
      r"$\aleph_0$, $\aleph_0$, $\mathfrak{c}$, $\mathfrak{c}$, $2^{\aleph_0}=\mathfrak{c}$ (or at least $2^{\aleph_0}$, identified with $\mathfrak{c}$ via binary expansions).",
      r"$|\mathbb{N}\cup\{-1,-2\}|$ equals", r"$\aleph_0$.",
      r"Writing $\infty+\infty=2\infty$ as if $\infty$ were a cardinal, or claiming $|\mathbb{R}^2|>|\mathbb{R}|$.",
      r"$|\mathbb{R}\times\mathbb{Q}|$.", r"$\mathfrak{c}\cdot\aleph_0=\mathfrak{c}$.",
      r"Why is $|\mathbb{R}|\le 2^{\aleph_0}$?", r"Each real has a binary expansion, giving a surjection $\{0,1\}^{\mathbb{N}}\to[0,1]$.")
    a(752, r"The axiom of choice (AC): the product of a family of nonempty sets is nonempty (a choice function exists). Equivalent (over ZF): Zorn's lemma; every set can be well-ordered; every vector space has a Hamel basis. Countable choice is enough for many analysis arguments (selecting $x_n\in U_n$). AC yields nonmeasurable sets (Vitali).",
      r"Where is AC used in ``every vector space has a basis''?",
      r"Zorn: order proper linearly independent sets by inclusion; a maximal one spans. The maximal element is not constructed explicitly in general.",
      r"A choice function on $\{A_i\}_{i\in I}$ picks", r"one element from each $A_i$.",
      r"Thinking AC is needed to choose one element from a single nonempty set, or from finitely many (ZF suffices).",
      r"Vitali set in $\mathbb{R}/\mathbb{Q}$: AC chooses", r"one representative from each coset of $\mathbb{Q}$.",
      r"Is AC needed to well-order $\mathbb{N}$?", r"No: the usual order already well-orders $\mathbb{N}$.")

    # Q foundational awareness
    a(753, r"Russell's paradox: unrestricted comprehension $\{x:P(x)\}$ is inconsistent. If $R=\{x:x\notin x\}$, then $R\in R\Leftrightarrow R\notin R$. ZFC repairs this by separation (comprehension only inside an already given set) and forbidding a universal set. Naive ``the set of all sets'' cannot exist in ZFC.",
      r"If a universe $U$ of all sets existed, what goes wrong with $R=\{x\in U:x\notin x\}$?",
      r"The same Russell contradiction: $R\in R$ iff $R\notin R$. So no universal set.",
      r"ZFC comprehension is restricted how?", r"Given a set $A$ and a formula $P$, $\{x\in A:P(x)\}$ exists; one cannot collect all $x$ in the universe satisfying $P$.",
      r"Treating ``the set of all sets'' or ``the set of all groups'' as a set rather than a proper class.",
      r"Does $\emptyset\in\emptyset$? Does this create Russell's paradox by itself?", r"No and no: foundation is separate; Russell needs unrestricted $\{x:x\notin x\}$.",
      r"Type theory / Russell's ramified types avoid the paradox by", r"forbidding $x\in x$ syntactically: a set lives at a higher type than its elements.")
    a(754, r"Syntax is the formal language: symbols, well-formed formulas, rules of inference, proofs ($\vdash$). Semantics is meaning in a structure: satisfaction, truth ($\models$). Soundness: provable implies true in all models. G\"odel completeness (first-order): conversely, if $\Gamma\models\phi$ then $\Gamma\vdash\phi$. A sentence can be true in one model and false in another.",
      r"Distinguish ``$G$ is a group'' as a syntactic axiom set vs a semantic statement about a particular $(G,\cdot)$.",
      r"The group axioms are strings one may derive theorems from. A particular set with an operation either satisfies those axioms (is a model) or not.",
      r"Soundness says that if $\vdash\phi$ then", r"every model satisfies $\phi$.",
      r"Confusing ``true'' with ``provable'' in a system that may be incomplete (G\"odel incompleteness for arithmetic).",
      r"Is ``$\mathbb{R}$ is complete'' a first-order property of the ordered field of reals?", r"No: completeness is a second-order / supremum statement about all subsets; many non-complete models satisfy the first-order theory of real closed fields.",
      r"Completeness theorem vs incompleteness theorem.", r"Completeness: first-order semantic entailment = syntactic derivability. Incompleteness: Peano arithmetic does not decide every arithmetic sentence.")
    a(755, r"The axiomatic viewpoint: a mathematical theory starts from undefined primitives and axioms, then derives theorems by stipulated rules. Models interpret the primitives so the axioms come out true. Changing an axiom (parallel postulate; AC; CH) changes the theorem set. Consistency is relative: one interprets a theory inside another (e.g. geometry in $\mathbb{R}^2$, ZFC in a universe of sets).",
      r"How does the parallel postulate illustrate the axiomatic method?",
      r"Euclid's first four axioms plus the parallel postulate give Euclidean geometry; replacing it by its negation gives consistent hyperbolic geometry (relative to the consistency of Euclidean / real analysis).",
      r"Undefined primitives in Peano arithmetic include", r"$0$ and the successor operation (plus axioms for $+$ and $\cdot$).",
      r"Treating axioms as ``obvious truths about the unique intended universe'' and rejecting independence results as defects.",
      r"A model of the group axioms is", r"any set with an associative operation, identity, and inverses.",
      r"Why can CH neither be proved nor refuted in ZFC (assuming ZFC is consistent)?", r"G\"odel and Cohen: $L$ satisfies CH, forcing extensions can violate it; both relative consistencies.")

    return F


